window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[302]={"id":"302","numero":302,"titre":"Tumeurs cutanées épithéliales et mélaniques","objectifs":[{"id":"302-1","rang":"A","rubrique":"Définition","titre":"Connaître les principales tumeurs cutanées","contenu":"<p>Les tumeurs cutanées se développent aux dépens des <span class=\"kw-def\">kératinocytes</span> (lignée épithéliale) ou des <span class=\"kw-def\">mélanocytes</span> (lignée pigmentaire). On en distingue <strong><span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>4</span> g</span>randes catégories</strong> selon l'origine cellulaire et le caractère bénin/malin.</p>\n      <table >\n        <thead>\n          <tr><th></th><th>Bénignes</th><th>Malignes</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <th>Épithéliales <span class=\"kw-def\">(kératinocytaires)</span></th>\n            <td><span class=\"kw-clinique\">Verrues à <span class=\"kw-etio\">HPV</span></span></td>\n            <td>\n              <strong><span class=\"kw-alerte\">Carcinome basocellulaire (CBC)</span></strong> — <span class=\"kw-chiffre\">tumeur humaine la plus fréquente</span>, en règle de bon <span class=\"kw-def\">pronostic</span> ;<br>\n              <strong><span class=\"kw-alerte\">Carcinome épidermoïde (CE)</span></strong> — agressif, métastases ganglionnaires possibles.\n            </td>\n          </tr>\n          <tr>\n            <th>Mélanocytaires</th>\n            <td><span class=\"kw-clinique\">Nævus</span> <span class=\"kw-def\">(grains de beauté)</span></td>\n            <td><strong><span class=\"kw-alerte\">Mélanome</span></strong> — <span class=\"kw-def\">pronostic</span> sombre au <span class=\"kw-def\">stade</span> métastatique, révolutionné par les nouvelles thérapies ciblées et l'<span class=\"kw-ttt\">immunothérapie</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>FR transversal.</strong> ☀️ À l'exception des <span class=\"kw-clinique\">verrues à HPV</span>, toutes ces tumeurs partagent un <span class=\"kw-def\">facteur de risque</span> commun : l'exposition aux <span class=\"kw-etio\">UV (A/B/C)</span>. Les <span class=\"kw-ttt\">UVA</span> ont une <span class=\"kw-bio\">phototoxicité directe sur l'ADN</span> + stress oxydatif (ROS) ; les <span class=\"kw-ttt\">UVB</span> sont mutagènes par formation de dimères de pyrimidines.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 162 — IST · 300 — Tumeur col-corps utérin</em></p>","frequence":1},{"id":"302-2","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la présentation clinique d’une tumeur épithéliale bénigne à HPV","contenu":"<p>Les <strong>verrues à <span class=\"kw-etio\">HPV</span></strong> (Human Papilloma Virus) sont des <span class=\"kw-def\">tumeurs épithéliales bénignes</span> liées à l'infection des kératinocytes par un papillomavirus humain. Présentation cutanée typique :</p>\n      <ul>\n        <li><strong><span class=\"kw-clinique\">Verrues vulgaires</span></strong> : <span class=\"kw-imagerie\">papules kératosiques rugueuses</span>, à surface verruqueuse, siégeant aux <span class=\"kw-clinique\">mains</span> et aux <span class=\"kw-clinique\">doigts</span> (zones de microtraumatismes répétés).</li>\n        <li><strong><span class=\"kw-clinique\">Verrues plantaires</span></strong> : <span class=\"kw-imagerie\">myrmécies</span> (<span class=\"kw-clinique\">lésion</span> unique douloureuse à la pression) ou <span class=\"kw-imagerie\">verrues en mosaïque</span> (plages multiples coalescentes), siégeant aux points d'appui plantaires.</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>À compléter.</strong> Les fiches sources du dossier <code>302-tumeurs-cutane/</code> ne détaillent pas plus avant la présentation clinique des verrues <span class=\"kw-etio\">HPV</span> (juste mentionnée en <span class=\"kw-def\">classification</span>). Pour le détail des présentations cliniques HPV-induites <span class=\"kw-clinique\">cutanées</span> et <span class=\"kw-clinique\">muqueuses</span> (condylomes), se référer à l'item 162.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 162 — IST · 300 — Tumeur col-corps utérin</em></p>","frequence":0},{"id":"302-3","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l’épidémiologie des tumeurs cutanées","contenu":"<p>Les <span class=\"kw-def\">carcinomes cutanés</span> représentent les <strong>cancers de l'adulte les plus fréquents au monde</strong> (<span class=\"kw-chiffre\">90 %</span> des cancers cutanés). Leur <span class=\"kw-def\">incidence</span> est en <strong>augmentation constante</strong> : allongement de la durée de vie + <span class=\"kw-etio\">UV</span> cumulés.</p>\n      <table >\n        <thead>\n          <tr><th></th><th>CBC</th><th>CE</th><th><span class=\"kw-clinique\">Mélanome</span></th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <th>Incidence (France)</th>\n            <td><span class=\"kw-chiffre\">80–150/100 000/an</span> ; <span class=\"kw-chiffre\">×2 en 20 ans</span></td>\n            <td><span class=\"kw-chiffre\">> 30/100 000/an</span></td>\n            <td><span class=\"kw-chiffre\">~10/100 000/an</span> ; <span class=\"kw-chiffre\">15 000 cas/an</span> en France</td>\n          </tr>\n          <tr>\n            <th>Âge médian</th>\n            <td><span class=\"kw-chiffre\">66 ans</span> ; flambée après <span class=\"kw-chiffre\">85 ans</span></td>\n            <td><span class=\"kw-chiffre\">76 ans</span> ; <span class=\"kw-chiffre\">> 60 ans</span></td>\n            <td><span class=\"kw-chiffre\">55 ans</span> ; exceptionnel chez l'enfant prépubère</td>\n          </tr>\n          <tr>\n            <th>Sex-ratio</th>\n            <td>Équilibré</td>\n            <td>Prédominance <span class=\"kw-clinique\">masculine</span></td>\n            <td><span class=\"kw-chiffre\">11ᵉ</span> cancer ♂ / <span class=\"kw-chiffre\">9ᵉ</span> ♀</td>\n          </tr>\n          <tr>\n            <th>Part des cancers cutanés</th>\n            <td><span class=\"kw-chiffre\">70 %</span> ; <span class=\"kw-chiffre\">30 %</span> de tous les cancers</td>\n            <td>~<span class=\"kw-chiffre\">20 %</span></td>\n            <td><span class=\"kw-chiffre\">2–3 %</span> de l'ensemble des cancers</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-def\">Mortalité</span></th>\n            <td>Quasi-nulle</td>\n            <td>Faible (mais agressif si évolué)</td>\n            <td><span class=\"kw-chiffre\">~1 700 décès/an</span> ; <span class=\"kw-alerte\">1ᵉʳ cancer en termes d'augmentation de fréquence</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>Tendance.</strong> <span class=\"kw-def\">Incidence</span> du <span class=\"kw-clinique\">CBC</span> a doublé en <span class=\"kw-chiffre\">20 ans</span> ; celle du <span class=\"kw-clinique\">mélanome</span> <strong>double tous les <span class=\"kw-chiffre\">10 ans</span></strong>. La <span class=\"kw-def\">mortalité</span> mélanique augmente moins vite que l'incidence grâce au diagnostic plus précoce de lésions plus fines (<span class=\"kw-bio\">Breslow</span> moyen plus bas).\n      </div>","frequence":0},{"id":"302-4","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge globale des tumeurs cutanées","contenu":"<p>La PEC d'une <span class=\"kw-clinique\">tumeur cutanée</span> suspecte repose sur <strong>4 axes</strong> communs aux <span class=\"kw-clinique\">CBC</span>, <span class=\"kw-clinique\">CE</span> et <span class=\"kw-clinique\">mélanomes</span> :</p>\n      <ul>\n        <li><strong>Confirmation histologique préalable</strong> — soit par <span class=\"kw-bio\">biopsie</span> (diagnostic incertain, <span class=\"kw-ttt\">chirurgie</span> complexe, zone orbitopalpébrale), soit par <span class=\"kw-bio\">exérèse à visée diagnostique</span> d'emblée si diagnostic très probable.</li>\n        <li><strong><span class=\"kw-ttt\">Exérèse</span> chirurgicale = traitement de référence</strong> — marges latérales conditionnées par le type (<span class=\"kw-chiffre\">3–10 mm</span> pour CBC/CE) et par le <span class=\"kw-bio\">Breslow</span> pour le <span class=\"kw-clinique\">mélanome</span> (<span class=\"kw-chiffre\">≤ 2 cm max</span>). Anesthésie locale en règle, jusqu'au <span class=\"kw-bio\">fascia</span> respecté pour le mélanome.</li>\n        <li><strong><span class=\"kw-alerte\">RCP indispensable</span></strong> en cas de forme évoluée, de CE groupe 2 (<span class=\"kw-chiffre\">≥ 1 FR de mauvais pronostic</span>), de <span class=\"kw-clinique\">mélanome</span> <span class=\"kw-def\">stade</span> III/IV, ou si la <span class=\"kw-ttt\">chirurgie</span> n'est pas réalisable d'emblée.</li>\n        <li><strong><span class=\"kw-def\">Suivi</span> clinique annuel à vie</strong> (au moins <span class=\"kw-chiffre\">5 ans</span>) + <span class=\"kw-clinique\">auto-dépistage</span> enseigné + <span class=\"kw-clinique\">photoprotection</span> renforcée.</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>Piège ⚠️.</strong> Toute <span class=\"kw-clinique\">lésion</span> <span class=\"kw-clinique\">pigmentée suspecte de mélanome</span> impose une <span class=\"kw-alerte\">exérèse complète d'emblée</span> (marges macroscopiques ≈ <span class=\"kw-chiffre\">1 cm</span>) — <span class=\"kw-alerte\"><strong>JAMAIS</strong> de biopsie partielle</span>, sauf exception : lésion de très grande taille dont l'<span class=\"kw-ttt\">exérèse</span> totale serait délabrante (visage).\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 292 — Diagnostic des cancers · 294 — Traitement des cancers · 295 — Prise en charge d'un malade cancéreux</em></p>","frequence":1},{"id":"302-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la présentation clinique et la démarche diagnostique devant un carcinome basocellulaire, épidermoïde","contenu":"<p><strong>Objectif majeur (⭐⭐⭐).</strong> Présentations cliniques opposées et démarche diagnostique différenciée entre <span class=\"kw-clinique\">CBC</span> et <span class=\"kw-clinique\">CE</span> :</p>\n      <table >\n        <thead>\n          <tr><th></th><th>CBC</th><th>CE (invasif)</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <th>Localisation</th>\n            <td>Zones photo-exposées (<span class=\"kw-clinique\">visage ++</span>) ; <span class=\"kw-alerte\">JAMAIS sur les muqueuses</span></td>\n            <td>Zones photo-exposées <span class=\"kw-clinique\">cutanées</span> <em>et</em> <span class=\"kw-clinique\">muqueuses</span> (lèvre inférieure, gland)</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-clinique\">Lésion</span> clé ⭐</th>\n            <td><strong><span class=\"kw-imagerie\">Perle</span></strong> = <span class=\"kw-clinique\">papule</span> rouge/rosée translucide, en relief, arrondie, recouverte de <span class=\"kw-imagerie\">télangiectasies</span> ; croissance lente ; parfois <span class=\"kw-imagerie\">bordure perlée caractéristique</span> en couronne</td>\n            <td>Clés sémiologiques (souvent associées) ⭐ : <strong><span class=\"kw-imagerie\">bourgeon</span></strong> + <strong><span class=\"kw-imagerie\">ulcération</span></strong> + <strong><span class=\"kw-imagerie\">croûte</span></strong> ; tumeur indurée saignant facilement</td>\n          </tr>\n          <tr>\n            <th>Variétés cliniques</th>\n            <td>\n              <strong>3 variétés</strong> :<br>\n              <strong>Nodulaire</strong> (la plus fréquente, visage, <span class=\"kw-clinique\">papule</span> perlée) ;<br>\n              <strong>Superficiel/pagétoïde</strong> (tronc, <span class=\"kw-clinique\">plaque</span> érythémato-squameuse à bords nets, fines perles en périphérie) ;<br>\n              <strong><span class=\"kw-alerte\">Sclérodermiforme</span></strong> (orifices de la face, cicatrice blanchâtre mal limitée — <span class=\"kw-alerte\">extension profonde sous-évaluée</span>).\n            </td>\n            <td>\n              CE invasif <strong>sur précurseur</strong> (<span class=\"kw-clinique\">kératose</span>, Bowen, leucoplasie) <em>ou</em> <strong>de novo</strong>.<br>\n              Bilan clinique : recherche d'une <span class=\"kw-clinique\">fixité aux plans profonds</span>, <span class=\"kw-clinique\">déficit nerveux</span> (V, VII), examen des <span class=\"kw-clinique\">aires de drainage</span>.\n            </td>\n          </tr>\n          <tr>\n            <th>Précurseurs</th>\n            <td><span class=\"kw-alerte\">Aucun</span></td>\n            <td>\n              <strong><span class=\"kw-clinique\">Kératose actinique</span></strong> (cutané) ;<br>\n              <strong><span class=\"kw-clinique\">Leucoplasie</span></strong> (muqueux ; rôle <span class=\"kw-etio\">tabac</span> + <span class=\"kw-etio\">UV</span>) ;<br>\n              <strong><span class=\"kw-clinique\">Maladie de Bowen</span></strong> = <span class=\"kw-clinique\">carcinome</span> in situ intra-épidermique.\n            </td>\n          </tr>\n          <tr>\n            <th>Confirmation</th>\n            <td colspan=\"2\">\n              <strong><span class=\"kw-bio\">Biopsie</span></strong> si diagnostic incertain ou <span class=\"kw-ttt\">chirurgie</span> complexe (orbitopalpébrale) ;<br>\n              <strong><span class=\"kw-ttt\">Exérèse</span> chirurgicale large d'emblée</strong> si diagnostic très probable, avec <span class=\"kw-bio\">analyse anatomopathologique</span> des marges.\n            </td>\n          </tr>\n          <tr>\n            <th>Anapath</th>\n            <td><span class=\"kw-bio\">Lobules de kératinocytes basophiles</span> (basaloïdes) en <span class=\"kw-bio\">disposition palissadique</span> en périphérie, <span class=\"kw-bio\">fentes de rétraction</span> ; 4 sous-types histologiques</td>\n            <td><span class=\"kw-bio\">Kératinocytes malpighiens de grande taille</span> en lobules/travées, <span class=\"kw-bio\">atypies cytonucléaires</span>, <span class=\"kw-bio\">globes cornés</span>, <span class=\"kw-bio\">ponts d'union</span> ; <span class=\"kw-bio\">envahissement</span> dermique ± hypodermique</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong>🔥 Piège du CBC sclérodermiforme.</strong> Aspect de <span class=\"kw-imagerie\">cicatrice blanchâtre banale</span> mal limitée → diagnostic souvent tardif, <span class=\"kw-alerte\">extension profonde sous-évaluée</span>. Forme la plus grave (et la plus rare) — penser au CBC devant toute cicatrice apparue spontanément en zone photo-exposée.\n      </div>\n      <div class=\"callout callout-warn\">\n        <strong>⚠️ Piège sémiologique fréquent.</strong> La règle <span class=\"kw-clinique\">ABCDE</span> = critères du <strong><span class=\"kw-clinique\">mélanome</span></strong>, pas du CBC/CE. Penser : <span class=\"kw-imagerie\">perle + télangiectasies</span> pour le CBC ; <span class=\"kw-imagerie\">bourgeon + ulcération + croûte</span> pour le CE.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 162 — IST · 194 — <span class=\"kw-def\">Lupus</span> - SAPL · 201 — Transplantation d'organe · 298 — Tumeur cavité buccale-nasosinusienne-cavum-VADS</em></p>","frequence":3},{"id":"302-6","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître le pronostic des carcinomes basocellulaires et épidermoïdes","contenu":"<p><span class=\"kw-def\">Pronostic</span> <strong>radicalement opposé</strong> entre <span class=\"kw-clinique\">CBC</span> (malignité essentiellement locale) et <span class=\"kw-clinique\">CE</span> (potentiel métastatique réel) :</p>\n      <table >\n        <thead>\n          <tr><th></th><th>CBC</th><th>CE</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <th><span class=\"kw-clinique\">Évolution</span></th>\n            <td>Locale, <span class=\"kw-clinique\">lente</span> ; destruction des structures de voisinage possible ; <span class=\"kw-alerte\">métastases exceptionnelles</span> (risque quasi-nul)</td>\n            <td><span class=\"kw-alerte\">Agressive</span> ; dissémination <span class=\"kw-bio\">lymphatique +++</span> (<span class=\"kw-chiffre\">80 %</span> des métastases), puis hématogène (poumons, foie, cerveau, os)</td>\n          </tr>\n          <tr>\n            <th>Risque métastatique</th>\n            <td>Quasi-nul</td>\n            <td><span class=\"kw-chiffre\">2 %</span> si CE cutané ; <span class=\"kw-chiffre\">20 %</span> si CE <span class=\"kw-alerte\">muqueux</span></td>\n          </tr>\n          <tr>\n            <th>Récidive locale</th>\n            <td colspan=\"2\"><span class=\"kw-chiffre\">5–10 %</span> après primotraitement, notamment dans les formes <span class=\"kw-alerte\">sclérodermiformes</span> (CBC) ou si <span class=\"kw-alerte\">exérèse incomplète/tardive</span> (CE)</td>\n          </tr>\n          <tr>\n            <th>FR de mauvais <span class=\"kw-def\">pronostic</span></th>\n            <td>\n              <strong>Localisations péri-orificielles</strong> (nez, paupières, oreilles) ;<br>\n              <strong><span class=\"kw-clinique\">Diamètre</span> élevé</strong> (<span class=\"kw-chiffre\">> 1 cm</span> zones à risque, <span class=\"kw-chiffre\">> 2 cm</span> ailleurs) ;<br>\n              Formes <strong>mal limitées</strong> (sclérodermiforme, infiltrant) ;<br>\n              <strong><span class=\"kw-ttt\">Exérèse</span> incomplète</strong> ou marges trop étroites ;<br>\n              Caractère <strong>récidivant</strong>.\n            </td>\n            <td>\n              <strong><span class=\"kw-alerte\">Immunodépression chronique</span></strong> ;<br>\n              <strong>Localisations à haut risque 🔥</strong> : péri-orificielles, muqueuses, cuir chevelu, peau pathologique (<span class=\"kw-clinique\">radiodermite</span>, brûlures, ulcères chroniques) ;<br>\n              <strong>Taille</strong> <span class=\"kw-chiffre\">> 1 cm</span> zones à risque, <span class=\"kw-chiffre\">> 2 cm</span> ailleurs ;<br>\n              <strong><span class=\"kw-bio\">Histologie</span></strong> : épaisseur <span class=\"kw-chiffre\">> 3 mm</span>, <span class=\"kw-bio\">invasion périnerveuse</span>, <span class=\"kw-bio\">emboles vasculaires</span>, <span class=\"kw-bio\">différenciation</span> moyenne/absente ;<br>\n              <strong>Marges insuffisantes</strong> (<span class=\"kw-chiffre\">4–6 mm</span>).\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p>Le CE se classe en <strong><span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>2</span> g</span>roupes pronostiques</strong> qui conditionnent la conduite :</p>\n      <table >\n        <thead>\n          <tr><th>Groupe</th><th>Définition</th><th><span class=\"kw-def\">RCP</span></th><th>Marges chirurgicales</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <th>1</th>\n            <td>Aucun FR de mauvais <span class=\"kw-def\">pronostic</span></td>\n            <td>Non nécessaire</td>\n            <td><span class=\"kw-chiffre\">4–6 mm</span></td>\n          </tr>\n          <tr>\n            <th>2</th>\n            <td><span class=\"kw-alerte\">≥ 1 FR de mauvais pronostic</span></td>\n            <td><strong>Indispensable</strong></td>\n            <td><span class=\"kw-chiffre\">> 6 mm</span> (<span class=\"kw-chiffre\">1 cm</span> si possible) ; <span class=\"kw-bio\">biopsie</span> préalable recommandée</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong>🔥 À retenir.</strong> <span class=\"kw-alerte\">Tout CE doit être considéré comme potentiellement agressif</span>. Le CBC est exceptionnellement responsable de décès, mais peut entraîner une destruction locale majeure (visage). À l'inverse, le CE peut tuer par dissémination ganglionnaire puis viscérale.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 194 — <span class=\"kw-def\">Lupus</span> - SAPL · 201 — Transplantation d'organe</em></p>","frequence":2},{"id":"302-7","rang":"A","rubrique":"Prise en charge","titre":"Connaître la prévention des carcinomes épidermoïdes et basocellulaires","contenu":"<p>La prévention des carcinomes cutanés repose sur <strong>2 axes</strong> complémentaires : photoprotection (primaire) et <span class=\"kw-def\">dépistage</span> des lésions précancéreuses (secondaire).</p>\n      <ul>\n        <li><strong><span class=\"kw-def\">Prévention primaire</span> — photoprotection</strong> :\n          <ul>\n            <li><span class=\"kw-clinique\">Éviter</span> les expositions au pic d'ensoleillement (<span class=\"kw-chiffre\">11h–16h</span>).</li>\n            <li><span class=\"kw-clinique\">Vêtements couvrants</span> + <span class=\"kw-clinique\">chapeau à larges bords</span> + <span class=\"kw-clinique\">lunettes</span>.</li>\n            <li><span class=\"kw-ttt\">Écran solaire SPF ≥ 50</span> sur zones découvertes, renouvellement <span class=\"kw-chiffre\">/ 2h</span>.</li>\n            <li><span class=\"kw-alerte\">CI absolue</span> des <span class=\"kw-ci\">cabines de bronzage UV</span> — classées <strong>cancérogènes certains (groupe 1 OMS)</strong>.</li>\n            <li>Photoprotection renforcée chez l'<span class=\"kw-clinique\">enfant</span> (<span class=\"kw-def\">terrain</span> sur lequel les <span class=\"kw-etio\">UV</span> impriment durablement).</li>\n          </ul>\n        </li>\n        <li><strong><span class=\"kw-def\">Prévention secondaire</span> — dépistage</strong> :\n          <ul>\n            <li><span class=\"kw-def\">Dépistage</span> du CE et de ses précurseurs recommandé après <span class=\"kw-chiffre\">50 ans</span> chez les sujets à risque (<span class=\"kw-clinique\">phototype</span> <span class=\"kw-clinique\">I–II</span>, ATCD personnel/familial, immunodéprimés, transplantés rénaux).</li>\n            <li>Traitement précoce des <strong><span class=\"kw-clinique\">kératoses actiniques</span></strong> : <span class=\"kw-ttt\">cryothérapie</span> à l'azote liquide, <span class=\"kw-ttt\">5-FU topique</span>, <span class=\"kw-ttt\">imiquimod crème</span>, <span class=\"kw-ttt\">photothérapie dynamique</span>.</li>\n            <li>Auto-<span class=\"kw-def\">surveillance</span> enseignée + examen tégumentaire annuel chez les très haut-risque.</li>\n          </ul>\n        </li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>⚠️ Idée reçue.</strong> Le <span class=\"kw-clinique\">bronzage</span> n'est pas un signe de santé — c'est un signal d'agression de l'ADN par les <span class=\"kw-etio\">UV</span>. Le <span class=\"kw-alerte\">bronzage en cabine UV</span> est classé <strong>cancérogène certain (groupe 1 OMS)</strong>, au même rang que le <span class=\"kw-etio\">tabac</span> et l'amiante.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 201 — Transplantation d'organe · 194 — <span class=\"kw-def\">Lupus</span> - SAPL</em></p>","frequence":0},{"id":"302-8","rang":"A","rubrique":"Définition","titre":"Connaître la définition et les principaux facteurs de risque des nævi","contenu":"<p>Un <strong><span class=\"kw-def\">nævus mélanocytaire</span></strong> est une <span class=\"kw-def\">prolifération bénigne de mélanocytes</span> groupés en <span class=\"kw-bio\">thèques</span> (amas cellulaires) dans l'épiderme et/ou le derme. C'est la tumeur mélanocytaire la plus fréquente — présente chez <strong>tous les individus</strong> (« grains de beauté »).</p>\n      <p><strong>3 formes anatomopathologiques</strong> selon la répartition des thèques :</p>\n      <ul>\n        <li><strong><span class=\"kw-bio\">Nævus jonctionnel</span></strong> — thèques dans la couche basale de l'épiderme ; forme prédominante chez l'<span class=\"kw-clinique\">enfant</span>, diminue au cours du vieillissement.</li>\n        <li><strong><span class=\"kw-bio\">Nævus dermique</span></strong> — strictement intradermique ; volontiers tubéreux, papuleux.</li>\n        <li><strong><span class=\"kw-bio\">Nævus mixte (composé)</span></strong> — composante à la fois jonctionnelle et dermique.</li>\n      </ul>\n      <table >\n        <thead>\n          <tr><th>Catégorie de FR</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <th><span class=\"kw-clinique\">Phototype</span></th>\n            <td><span class=\"kw-clinique\">Phototype clair</span> (I–II) — peau claire, cheveux blonds/roux, yeux clairs, éphélides</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-etio\">Exposition solaire</span></th>\n            <td>Expositions <span class=\"kw-clinique\">intermittentes et intenses</span>, surtout dans l'<span class=\"kw-alerte\">enfance</span> (mêmes FR que ceux du <span class=\"kw-clinique\">mélanome</span>)</td>\n          </tr>\n          <tr>\n            <th>Immunodépression</th>\n            <td><span class=\"kw-clinique\">Transplantés d'organe</span>, traitements <span class=\"kw-ttt\">immunosuppresseurs</span>, infection <span class=\"kw-etio\">VIH</span></td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-etio\">Génétique</span></th>\n            <td><strong><span class=\"kw-alerte\">Syndrome des nævus atypiques</span></strong> : <span class=\"kw-chiffre\">> 50 nævus</span>, souvent <span class=\"kw-chiffre\">> 6 mm</span>, aspects atypiques (« œuf sur le plat »), transmission familiale possible</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>Histoire naturelle.</strong> Apparition vers <span class=\"kw-chiffre\">4–5 ans</span> → plateau vers <span class=\"kw-chiffre\">40 ans</span> (~<span class=\"kw-chiffre\">20 nævus</span> en moyenne) → régression progressive et raréfaction après <span class=\"kw-chiffre\">60 ans</span>. Pendant la <span class=\"kw-clinique\">grossesse</span>, augmentation de la taille (abdomen ++) et de la pigmentation possibles par <span class=\"kw-bio\">immunomodulation</span> — <span class=\"kw-ttt\">exérèse</span> si doute diagnostique.\n      </div>","frequence":0},{"id":"302-9","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les diagnostics différentiels des nævi","contenu":"<p>Les principaux diagnostics différentiels d'un nævus mélanocytaire commun sont d'autres <span class=\"kw-def\">lésions pigmentées cutanées</span> bénignes — et surtout <strong>le <span class=\"kw-clinique\">mélanome</span> débutant</strong>, qu'il faut savoir évoquer en priorité.</p>\n      <table >\n        <thead>\n          <tr><th>DD</th><th>Aspect clinique</th><th>Localisation</th><th>Élément distinctif</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <th><span class=\"kw-clinique\">Lentigo</span></th>\n            <td><span class=\"kw-imagerie\">Macule pigmentée</span> à contours géographiques (« tache de peinture »), teinte uniforme et fixe</td>\n            <td>Zones photo-exposées, zones de coup de soleil</td>\n            <td>Bénin, dit « tache de vieillesse » ; ne disparaît pas</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-clinique\">Éphélides</span></th>\n            <td><span class=\"kw-imagerie\">Macules millimétriques brun-clair</span></td>\n            <td>Zones photo-exposées</td>\n            <td>« Taches de rousseur » du sujet <span class=\"kw-clinique\">roux</span> ; s'accentuent au soleil, s'effacent avec le temps</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-clinique\">Histiocytofibrome</span></th>\n            <td><span class=\"kw-imagerie\">Nodule ferme à halo brunâtre</span>, <strong>induration palpable</strong>, invagination centrale</td>\n            <td>Membres inférieurs ++</td>\n            <td>Apparaît typiquement <span class=\"kw-etio\">à distance d'une piqûre d'insecte</span></td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-clinique\">Kératose séborrhéique</span></th>\n            <td><span class=\"kw-imagerie\">Lésion verruqueuse rugueuse</span> recouverte d'un enduit squamo-kératosique gras, bordure nette et abrupte</td>\n            <td>Visage, décolleté, dos</td>\n            <td><span class=\"kw-clinique\">Lésion</span> pigmentée la plus fréquente <span class=\"kw-chiffre\">> 40 ans</span> ; <span class=\"kw-alerte\">jamais maligne</span> ; pas liée au soleil</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-clinique\">Angiome thrombosé</span></th>\n            <td><span class=\"kw-imagerie\">Lésion bleu-noir, ferme</span></td>\n            <td>Tronc, membres</td>\n            <td>Tumeur vasculaire bénigne ; dermatoscopie tranche</td>\n          </tr>\n          <tr>\n            <th><strong><span class=\"kw-alerte\">Mélanome débutant</span></strong></th>\n            <td>SSM (<span class=\"kw-clinique\">macule</span>) ou nodulaire ; <strong>aspect discordant</strong> (vilain petit canard)</td>\n            <td>Tout site</td>\n            <td><span class=\"kw-alerte\">⚠️ DD le plus crucial</span> — toujours évoquer en premier</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong>🔥 DD à ne JAMAIS manquer.</strong> Le <span class=\"kw-clinique\">mélanome</span> <span class=\"kw-clinique\">débutant</span> (SSM ou nodulaire) est le DD le plus dangereux. En cas de doute : <span class=\"kw-bio\">dermatoscopie</span> par opérateur formé, et au moindre doute persistant, <strong><span class=\"kw-ttt\">exérèse</span> à visée diagnostique</strong> — temps de réflexion non rigoureusement requis (<span class=\"kw-alerte\">urgence</span> diagnostique).\n      </div>","frequence":0},{"id":"302-10","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la physiopathologie des nævi","contenu":"<p>Le <span class=\"kw-def\">mélanocyte</span> est une cellule d'origine <span class=\"kw-bio\">neuro-ectodermique</span> (exprime la <span class=\"kw-bio\">protéine S100</span>), disposée de manière isolée entre les kératinocytes à la <span class=\"kw-bio\">jonction dermo-épidermique</span> dans un rapport de <span class=\"kw-chiffre\">1 mélanocyte / 20–30 kératinocytes</span>. Sa fonction : produire la <span class=\"kw-bio\">mélanine</span>, transférée aux kératinocytes via des dendrites, qui photoprotège l'ADN des <span class=\"kw-etio\">UV</span>.</p>\n      <p>Le <strong>nævus</strong> est une <span class=\"kw-def\">accumulation de mélanocytes groupés en thèques</span> (amas) dans l'épiderme et/ou le derme. Les 3 formes anapath se distinguent selon la localisation des thèques :</p>\n      <ul>\n        <li><strong><span class=\"kw-bio\">Nævus jonctionnel</span></strong> : thèques dans la couche basale de l'épiderme (forme de l'enfant).</li>\n        <li><strong><span class=\"kw-bio\">Nævus dermique</span></strong> : thèques strictement intradermiques.</li>\n        <li><strong><span class=\"kw-bio\">Nævus mixte (composé)</span></strong> : composantes jonctionnelle + dermique.</li>\n      </ul>\n      <p><strong>Voie moléculaire — MAPK et sénescence oncogène-induite.</strong> La voie de signalisation <span class=\"kw-bio\">RAS → RAF → MEK → ERK</span> (voie <span class=\"kw-bio\">MAPK</span>) contrôle la prolifération mélanocytaire. Environ <span class=\"kw-chiffre\">80 %</span> des nævi communs portent une mutation activatrice de <strong><span class=\"kw-bio\">BRAF V600E</span></strong> (substitution Valine→acide Glutamique au codon 600), qui active constitutivement MEK puis ERK. Cette activation déclenche d'abord une <span class=\"kw-clinique\">prolifération mélanocytaire</span> — c'est ce qui forme le nævus — puis très rapidement une <strong><span class=\"kw-bio\">sénescence oncogène-induite</span></strong> (médiée par <span class=\"kw-bio\">p16<sup>INK4a</sup></span>) qui <span class=\"kw-clinique\">arrête la prolifération</span>. Le nævus reste alors <strong>stable et bénin</strong> toute la vie.</p>\n      <div class=\"callout callout-danger\">\n        <strong>🔥 De la sénescence au <span class=\"kw-clinique\">mélanome</span>.</strong> <span class=\"kw-bio\">BRAF V600E</span> seul <strong>n'est pas suffisant</strong> pour transformer un nævus en mélanome. La <span class=\"kw-alerte\">levée de la sénescence oncogène-induite</span> — par accumulation de mutations additionnelles (<span class=\"kw-bio\">perte de p16<sup>INK4a</sup></span>, mutations <span class=\"kw-bio\">PTEN</span>, <span class=\"kw-bio\">NRAS</span>, <span class=\"kw-bio\">TERT</span>) — est l'événement clé de la transformation maligne. C'est aussi pourquoi les <strong>thérapies ciblées anti-BRAF + anti-MEK</strong> (vémurafénib + cobimétinib, dabrafénib + tramétinib) sont efficaces sur les mélanomes <span class=\"kw-bio\">V600E/K</span> métastatiques.\n      </div>\n      <div class=\"callout callout-info\">\n        <strong>Distinction nævus / <span class=\"kw-clinique\">mélanome</span>.</strong> Elle se fait sur l'<span class=\"kw-bio\">architecture</span> histologique — régulière en thèques bien limitées (nævus) <em>versus</em> anarchique avec <span class=\"kw-bio\">migration pagétoïde</span> de cellules isolées dans le haut de l'épiderme (mélanome) — <strong>pas sur la cytologie seule</strong> : la <span class=\"kw-alerte\">dysplasie cytologique d'un mélanocyte n'est pas synonyme de malignité</span>.\n      </div>","frequence":0},{"id":"302-11","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques du mélanome","contenu":"<p>Le diagnostic clinique du <span class=\"kw-clinique\">mélanome</span> repose sur <strong>2 règles complémentaires</strong> (<span class=\"kw-clinique\">ABCDE</span> + <span class=\"kw-clinique\">vilain petit canard</span>) et la reconnaissance des <strong>7 formes anatomocliniques</strong>.</p>\n      <p><strong>Règle <span class=\"kw-clinique\">ABCDE</span></strong> — diagnostic évoqué si <span class=\"kw-chiffre\">≥ 2 critères</span> présents :</p>\n      <ul>\n        <li><strong>A</strong>symétrie de la <span class=\"kw-clinique\">lésion</span> ;</li>\n        <li><strong>B</strong>ords irréguliers (encochés ou polycycliques) ;</li>\n        <li><strong>C</strong>ouleur inhomogène ;</li>\n        <li><strong>D</strong>iamètre <span class=\"kw-chiffre\">> 6 mm</span> <span class=\"kw-alerte\">(et non pas > 1 cm — piège fréquent)</span> ; critère non spécifique ;</li>\n        <li><strong>É</strong>volution récente documentée (modification de taille, forme, couleur, relief).</li>\n      </ul>\n      <p><strong>Règle du <span class=\"kw-clinique\">vilain petit canard</span></strong> — chez un patient donné, les nævus sont globalement similaires ; un nævus <span class=\"kw-alerte\">discordant</span> doit faire suspecter un <span class=\"kw-clinique\">mélanome</span>. <strong><span class=\"kw-chiffre\">80 %</span> des mélanomes sont détectés par le patient lui-même</strong> avant le médecin.</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/302/melanome-source.png\" alt=\"Mélanome — règles diagnostiques cliniques\" loading=\"lazy\">\n        <figcaption>Source : fiche pédagogique référente — Mélanomes (302).</figcaption>\n      </figure>\n      <p><strong>Signes fonctionnels</strong> (tardifs) : <span class=\"kw-clinique\">prurit</span>, <span class=\"kw-clinique\">saignement au contact</span>. <strong>Localisations particulières</strong> : <span class=\"kw-clinique\">mélanome unguéal</span> (bande pigmentée longitudinale s'élargissant, <span class=\"kw-chiffre\">≥ 5 mm de large</span>) ; <span class=\"kw-clinique\">mélanome muqueux</span> (tache noire plane). La <span class=\"kw-bio\">dermatoscopie</span> (opérateur formé,<span class=\"kw-chiffre\"> 2 ans</span> d'apprentissage) augmente sensibilité et spécificité.</p>\n      <p><strong>7 formes anatomocliniques</strong> :</p>\n      <table >\n        <thead>\n          <tr><th>Forme</th><th>Fréquence</th><th><span class=\"kw-def\">Terrain</span></th><th>Caractéristiques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <th>SSM <em>(Superficial Spreading Melanoma)</em></th>\n            <td><span class=\"kw-chiffre\">60–70 %</span></td>\n            <td><span class=\"kw-chiffre\">40–50 ans</span></td>\n            <td><span class=\"kw-imagerie\">Macule rouge-brun</span> ; ♀ membres inférieurs, ♂ dos ; phase horizontale puis verticale</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-alerte\">Nodulaire</span></th>\n            <td><span class=\"kw-chiffre\">10–30 %</span></td>\n            <td>Indifférent</td>\n            <td><strong>Forme la plus agressive 🔥</strong> ; <span class=\"kw-imagerie\">nodule arrondi bleu/noir</span> (parfois achromique) ; <span class=\"kw-alerte\">croissance verticale d'emblée</span> (pas de phase horizontale)</td>\n          </tr>\n          <tr>\n            <th>Dubreuilh <em>(LLM)</em></th>\n            <td><span class=\"kw-chiffre\">4–10 %</span></td>\n            <td><span class=\"kw-chiffre\">> 60 ans</span>, féminin</td>\n            <td><span class=\"kw-imagerie\">Macule brunâtre du visage</span> ; <span class=\"kw-clinique\">évolution</span> horizontale lente puis nodules verticaux ; FR : exposition chronique cumulative</td>\n          </tr>\n          <tr>\n            <th>Acral lentigineux</th>\n            <td><span class=\"kw-chiffre\">2–5 %</span></td>\n            <td>Sujets à peau pigmentée</td>\n            <td><span class=\"kw-imagerie\">Macule brune à bords déchiquetés</span> ; <span class=\"kw-clinique\">paumes, plantes, appareil unguéal</span> ; non lié au soleil</td>\n          </tr>\n          <tr>\n            <th>Muqueux</th>\n            <td><span class=\"kw-chiffre\">~5 %</span></td>\n            <td>Indifférent</td>\n            <td>Muqueuses anorectale, nasale, buccale ; <span class=\"kw-alerte\">non lié au soleil</span></td>\n          </tr>\n          <tr>\n            <th>Uvéal</th>\n            <td>Rare</td>\n            <td>Adulte</td>\n            <td><strong>Cancer de l'œil le plus fréquent chez l'adulte</strong></td>\n          </tr>\n          <tr>\n            <th>Desmoplastique</th>\n            <td>Rare</td>\n            <td>Tête/cou</td>\n            <td><span class=\"kw-imagerie\">Plaque indurée ou nodule achromique</span> ; zones photo-exposées</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong>🔥 <span class=\"kw-clinique\">Mélanome</span> nodulaire.</strong> Forme <span class=\"kw-alerte\">la plus agressive</span> : croissance d'emblée verticale, <span class=\"kw-alerte\">pas de phase horizontale</span>, n'applique <strong>PAS la règle <span class=\"kw-clinique\">ABCDE</span></strong>. Le critère <strong>É</strong>volution suffit pour la suspicion. <span class=\"kw-def\">Diagnostic différentiel</span> piège : <span class=\"kw-clinique\">naevus</span> achromique, angiome thrombosé.\n      </div>\n      <div class=\"callout callout-warn\">\n        <strong>⚠️ Confirmation.</strong> Toujours par <strong><span class=\"kw-ttt\">exérèse</span> complète à visée diagnostique</strong>, sous anesthésie locale, emportant la tumeur jusqu'à l'<span class=\"kw-bio\">hypoderme</span>. <span class=\"kw-alerte\">JAMAIS de biopsie partielle</span>, sauf si <span class=\"kw-clinique\">lésion</span> de très grande taille dont l'exérèse totale serait délabrante (visage).\n      </div>","frequence":1},{"id":"302-12","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître l’évolution et le pronostic du mélanome","contenu":"<p><strong>Objectif majeur (⭐⭐⭐⭐⭐).</strong> Le <span class=\"kw-def\">pronostic</span> du <span class=\"kw-clinique\">mélanome</span> dépend essentiellement de l'<span class=\"kw-bio\">indice de Breslow</span> (épaisseur <span class=\"kw-etio\">tumorale</span> histologique maximale) et de l'extension métastatique. <strong>3 axes</strong> structurent le pronostic.</p>\n      <p><strong>1 · Risques évolutifs</strong> :</p>\n      <table >\n        <thead>\n          <tr><th><span class=\"kw-def\">Stade</span></th><th><span class=\"kw-def\">Pronostic</span></th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <th><span class=\"kw-clinique\">In situ</span></th>\n            <td>Guérison constante après <span class=\"kw-ttt\">exérèse</span> + marge élargie</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-clinique\">Récidive locale</span></th>\n            <td>Sur le site <span class=\"kw-etio\">tumoral</span> initial</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-clinique\">Métastases en transit</span></th>\n            <td>Cutanées ou sous-cutanées, entre la tumeur et le 1ᵉʳ relais ganglionnaire</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-clinique\">Métastases ganglionnaires</span></th>\n            <td>Régionales, par dissémination lymphatique</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-alerte\">Métastases viscérales</span></th>\n            <td>Souvent après métastases ganglionnaires ; <strong>n'importe quel organe</strong> (foie, poumon, cerveau, os)</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>2 · FR de mauvais <span class=\"kw-def\">pronostic</span> selon le <span class=\"kw-def\">stade</span></strong> (<span class=\"kw-def\">classification</span> <span class=\"kw-bio\">AJCC</span> en 4 stades) :</p>\n      <table >\n        <thead>\n          <tr><th>Stade</th><th>FR de mauvais pronostic</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <th>I–II <span class=\"kw-def\">(localisé)</span></th>\n            <td>\n              <strong><span class=\"kw-alerte\">Indice de Breslow</span></strong> = <strong>FACTEUR N°1</strong> (épaisseur <span class=\"kw-etio\">tumorale</span> histologique max) ;<br>\n              <strong><span class=\"kw-bio\">Indice de Clark</span></strong> (niveau d'invasion en profondeur, <em>utilisé en complément du <span class=\"kw-chiffre\">Breslow</span></em>) ;<br>\n              <strong><span class=\"kw-clinique\">Ulcération</span></strong> (clinique et/ou histologique) ;<br>\n              <strong><span class=\"kw-clinique\">Sexe masculin</span></strong> ;<br>\n              <strong><span class=\"kw-bio\">Index mitotique</span></strong> ;<br>\n              <strong>Sous-type histologique</strong> ;<br>\n              <strong>Localisation</strong> (tête / tronc) ;<br>\n              <strong><span class=\"kw-bio\">Envahissement</span> du <span class=\"kw-bio\">ganglion sentinelle</span></strong>.\n            </td>\n          </tr>\n          <tr>\n            <th>III <span class=\"kw-def\">(ganglionnaire)</span></th>\n            <td>\n              <strong>Nombre / taille</strong> des ganglions envahis ;<br>\n              <strong><span class=\"kw-bio\">Rupture capsulaire</span></strong> ;<br>\n              <strong><span class=\"kw-clinique\">Ulcération</span></strong> (garde un poids péjoratif à ce <span class=\"kw-def\">stade</span>).\n            </td>\n          </tr>\n          <tr>\n            <th>IV <span class=\"kw-def\">(métastatique)</span></th>\n            <td>\n              <strong><span class=\"kw-bio\">LDH élevées</span></strong> ;<br>\n              <strong><span class=\"kw-chiffre\">> 3 organes</span></strong> atteints ;<br>\n              <strong><span class=\"kw-chiffre\">> 3 métastases hépatiques</span></strong> ;<br>\n              <strong><span class=\"kw-alerte\">Métastases cérébrales</span></strong> symptomatiques et/ou <span class=\"kw-chiffre\">≥ 3</span>.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>2 bis · <span class=\"kw-def\">Classification</span> <span class=\"kw-bio\">T</span> AJCC 8ᵉ édition</strong> — basée sur le <span class=\"kw-bio\">Breslow</span> et l'<span class=\"kw-clinique\">ulcération</span> :</p>\n      <table >\n        <thead>\n          <tr><th>Catégorie T</th><th><span class=\"kw-chiffre\">Breslow</span></th><th>Sans <span class=\"kw-clinique\">ulcération</span></th><th>Avec ulcération</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <th><span class=\"kw-bio\">T1</span></th>\n            <td><span class=\"kw-chiffre\">≤ 1,0 mm</span></td>\n            <td><span class=\"kw-bio\">T1a</span> : <span class=\"kw-chiffre\">&lt; 0,8 mm</span> sans <span class=\"kw-clinique\">ulcération</span></td>\n            <td><span class=\"kw-bio\">T1b</span> : <span class=\"kw-chiffre\">0,8–1,0 mm</span> OU <span class=\"kw-chiffre\">&lt; 0,8 mm</span> avec <span class=\"kw-clinique\">ulcération</span></td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-bio\">T2</span></th>\n            <td><span class=\"kw-chiffre\">&gt; 1,0–2,0 mm</span></td>\n            <td><span class=\"kw-bio\">T2a</span></td>\n            <td><span class=\"kw-bio\">T2b</span></td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-bio\">T3</span></th>\n            <td><span class=\"kw-chiffre\">&gt; 2,0–4,0 mm</span></td>\n            <td><span class=\"kw-bio\">T3a</span></td>\n            <td><span class=\"kw-bio\">T3b</span></td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-alerte\">T4</span></th>\n            <td><span class=\"kw-chiffre\">&gt; 4,0 mm</span></td>\n            <td><span class=\"kw-bio\">T4a</span></td>\n            <td><span class=\"kw-alerte\">T4b</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>Articulation T + N + M → <span class=\"kw-def\">stade</span> AJCC.</strong> Les stades cliniques I-IV combinent T (épaisseur ± <span class=\"kw-clinique\">ulcération</span>), <span class=\"kw-bio\">N</span> (ganglions : N0 / N1-3 selon nombre et type micro/macro) et <span class=\"kw-bio\">M</span> (métastases à distance : M0 / M1a peau-tissus mous / M1b poumon / M1c viscérales hors SNC / M1d cérébrales). Le seuil opérationnel à retenir : <strong><span class=\"kw-bio\">T2a</span> et au-delà</strong> (<span class=\"kw-chiffre\">Breslow</span> &gt;<span class=\"kw-chiffre\"> 1 mm</span>) <strong>OU</strong> <span class=\"kw-clinique\">ulcération</span> à tout Breslow → <span class=\"kw-bio\">ganglion sentinelle</span> indiqué.\n      </div>\n      <p><strong>3 · Survie à<span class=\"kw-chiffre\"> 5 ans</span></strong> (titre informatif) :</p>\n      <table >\n        <thead>\n          <tr><th>Profil</th><th>Survie à<span class=\"kw-chiffre\"> 5 ans</span></th></tr>\n        </thead>\n        <tbody>\n          <tr><th><span class=\"kw-bio\">Breslow ≤ 1 mm</span> (± <span class=\"kw-clinique\">ulcération</span>)</th><td><span class=\"kw-chiffre\">> 93 %</span></td></tr>\n          <tr><th><span class=\"kw-bio\">Breslow ≤ 2 mm</span> sans <span class=\"kw-clinique\">ulcération</span></th><td><span class=\"kw-chiffre\">> 80 %</span></td></tr>\n          <tr><th><span class=\"kw-bio\">Breslow 2–4 mm</span> et/ou <span class=\"kw-clinique\">ulcération</span></th><td><span class=\"kw-chiffre\">> 50 %</span></td></tr>\n          <tr><th>Atteinte ganglionnaire <span class=\"kw-clinique\">microscopique</span></th><td><span class=\"kw-chiffre\">> 70 %</span></td></tr>\n          <tr><th>Atteinte ganglionnaire <span class=\"kw-clinique\">macroscopique</span></th><td><span class=\"kw-chiffre\">> 50 %</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong>🔥 Indice de <span class=\"kw-chiffre\">Breslow</span> = facteur pronostique N°1.</strong> Toute tumeur de <span class=\"kw-chiffre\">Breslow > 1 mm</span> <strong>OU</strong> ulcérée → <span class=\"kw-bio\">ganglion sentinelle</span> proposé. La détection d'une <span class=\"kw-bio\">micrométastase sentinelle</span> fait passer en <span class=\"kw-def\">stade</span> <span class=\"kw-chiffre\">3a</span> et autorise un traitement adjuvant <span class=\"kw-chiffre\">1 an</span> (anti-PD1, ou anti-BRAF + anti-MEK si mutation V600E/K).\n      </div>\n      <div class=\"callout callout-warn\">\n        <strong>⚠️ À retenir.</strong> À <span class=\"kw-bio\">Breslow identique</span>, les 7 formes anatomocliniques ont un <span class=\"kw-def\">pronostic</span> <strong>globalement comparable</strong>. Le pronostic <strong>NE DÉPEND PAS</strong> de la forme clinique mais de la <span class=\"kw-alerte\">profondeur</span>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 295 — Prise en charge d'un malade cancéreux · 191 — <span class=\"kw-clinique\">Fièvre</span> chez l'immunodéprimé</em></p>","frequence":5},{"id":"302-13","rang":"A","rubrique":"Prise en charge","titre":"Connaître les modalités de prévention du mélanome","contenu":"<p>Comme pour les carcinomes cutanés, la prévention du <span class=\"kw-clinique\">mélanome</span> repose sur <strong>2 axes</strong>. Le profil d'exposition à cibler est cependant différent : <span class=\"kw-alerte\">expositions intenses et intermittentes de l'enfance</span> (et non chroniques cumulées comme pour le CE).</p>\n      <ul>\n        <li><strong><span class=\"kw-def\">Prévention primaire</span> — photoprotection ciblée enfance</strong> :\n          <ul>\n            <li><span class=\"kw-clinique\">Éviter</span> les expositions intenses et les <span class=\"kw-alerte\">coups de soleil</span>, surtout dans l'enfance.</li>\n            <li><span class=\"kw-clinique\">Vêtements couvrants</span>, <span class=\"kw-clinique\">chapeau</span>, lunettes ; <span class=\"kw-ttt\">écran SPF 50+</span> sur zones découvertes.</li>\n            <li><span class=\"kw-alerte\">CI absolue</span> des <span class=\"kw-ci\">cabines UV</span> (cancérogène certain groupe 1 OMS).</li>\n            <li><span class=\"kw-clinique\">Information</span> sur les risques liés aux <span class=\"kw-etio\">UV naturels et artificiels</span>.</li>\n          </ul>\n        </li>\n        <li><strong><span class=\"kw-def\">Prévention secondaire</span> — dépistage précoce</strong> :\n          <ul>\n            <li>Formation des médecins à l'examen tégumentaire complet (règle <span class=\"kw-clinique\">ABCDE</span> + <span class=\"kw-clinique\">vilain petit canard</span>), référer à un expert si doute.</li>\n            <li>Informer la population générale sur les signes d'appel ; inciter à consulter sans tarder.</li>\n            <li><span class=\"kw-def\">Suivi</span> <span class=\"kw-clinique\">dermatologique annuel à vie</span> chez les patients à <strong>très haut risque</strong> : ATCD personnel de <span class=\"kw-clinique\">mélanome</span>, syndrome des nævus atypiques.</li>\n            <li>Outils de <span class=\"kw-def\">suivi</span> : <span class=\"kw-bio\">dermatoscopie</span>, <span class=\"kw-bio\">surveillance photographique</span>, <span class=\"kw-bio\">calques de suivi</span>.</li>\n            <li><strong>Auto-<span class=\"kw-def\">surveillance</span></strong> enseignée à tous : repérage précoce des lésions suspectes, rythmicité, consulter sans tarder en cas de <span class=\"kw-clinique\">lésion</span> inhabituelle.</li>\n          </ul>\n        </li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>⚠️ Profil de risque mélanique.</strong> Ce sont les <span class=\"kw-alerte\">expositions solaires intenses et intermittentes</span> (surtout pendant l'<span class=\"kw-clinique\">enfance</span>) qui sont le FR majeur du SSM — pas l'exposition chronique cumulée (qui prédomine pour le CE et le Dubreuilh). <strong>La photoprotection de l'enfance est l'enjeu N°1 de la <span class=\"kw-def\">prévention primaire</span>.</strong>\n      </div>","frequence":1},{"id":"302-14","rang":"B","rubrique":"Contenu multimédia","titre":"Photographie d’une lésion précancéreuse cutanée","contenu":"<p>Le précurseur cutané emblématique du CE est la <strong><span class=\"kw-clinique\">kératose actinique</span></strong> (<span class=\"kw-clinique\">lésion</span> précancéreuse photo-induite). Sémiologie attendue :</p>\n      <ul>\n        <li><span class=\"kw-imagerie\">Lésion squameuse ou croûteuse</span>, multiples possibles, ± érythémateuse ou chamoisée ;</li>\n        <li><strong>Fines rugosités à la palpation</strong> — « <span class=\"kw-imagerie\">papier de verre</span> » (signe palpatoire pathognomonique) ;</li>\n        <li><span class=\"kw-clinique\">Saigne facilement</span> après grattage ; parfois micro-ulcérée ;</li>\n        <li>Siège <span class=\"kw-clinique\">photo-exposé</span> : <span class=\"kw-imagerie\">visage</span>, <span class=\"kw-imagerie\">dos des mains</span>, <span class=\"kw-imagerie\">scalp chauve</span>, <span class=\"kw-imagerie\">pavillon des oreilles</span>, tempes, front, bras ;</li>\n        <li><span class=\"kw-alerte\">Signes de cancérisation à surveiller</span> ⚠️ : <strong>bourrelet induré</strong>, <strong><span class=\"kw-clinique\">ulcération</span></strong>, rougeur excessive, kératinisation en cornes → <span class=\"kw-bio\">biopsie ou exérèse</span> obligatoire.</li>\n      </ul>\n      <p><strong><span class=\"kw-clinique\">Évolution</span></strong> : disparition spontanée, persistance, ou <span class=\"kw-alerte\">progression vers un CE invasif</span> (<span class=\"kw-chiffre\">10–25 %</span> des cas, potentiel limité). <strong>Traitement non chirurgical</strong> ⭐ : <span class=\"kw-ttt\">cryothérapie azote liquide</span>, <span class=\"kw-ttt\">5-FU crème</span>, <span class=\"kw-ttt\">imiquimod crème</span>, <span class=\"kw-ttt\">photothérapie dynamique</span>, <span class=\"kw-ttt\">électrocoagulation</span>, <span class=\"kw-ttt\">laser</span> CO2.</p>\n      <div class=\"callout callout-warn\">\n        <strong>À compléter.</strong> Image à enrichir manuellement (Pilly, Collège de Dermatologie, ou recherche web ciblée). Sémio attendue sur l'image : <span class=\"kw-clinique\">lésion</span> squameuse/croûteuse rosée ou chamoisée, rugosité au toucher (« papier de verre »), siège photo-exposé chez sujet <span class=\"kw-chiffre\">> 60 ans</span> à <span class=\"kw-clinique\">phototype</span> clair.\n      </div>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/malignant-melanoma","label":"Radiopaedia : Malignant melanoma"}]},{"id":"302-15","rang":"B","rubrique":"Contenu multimédia","titre":"Photographie d’un carcinome basocellulaire","contenu":"<p>Le CBC se présente sous <strong>3 variétés cliniques distinctes</strong>, à reconnaître devant une photographie en zone photo-exposée :</p>\n      <table >\n        <thead>\n          <tr><th>Variété</th><th>Aspect clinique</th><th>Localisation</th><th>Piège DD</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <th>CBC <strong>nodulaire</strong> <span class=\"kw-def\">(le plus fréquent)</span></th>\n            <td><strong><span class=\"kw-imagerie\">Papule perlée translucide</span></strong> ⭐, ferme, bien limitée, lisse, avec <strong><span class=\"kw-imagerie\">télangiectasies</span></strong> ; <span class=\"kw-imagerie\">bordure perlée caractéristique</span> en couronne, parfois <span class=\"kw-clinique\">ulcération</span> centrale (forme ulcéro-bourgeonnante)</td>\n            <td><span class=\"kw-clinique\">Visage</span> du sujet âgé</td>\n            <td>Kyste sébacé ; <span class=\"kw-clinique\">lésion</span> pigmentée → « CBC tatoué » → DD <span class=\"kw-clinique\">mélanome</span></td>\n          </tr>\n          <tr>\n            <th>CBC <strong>superficiel (pagétoïde)</strong></th>\n            <td><span class=\"kw-imagerie\">Plaque érythémato-squameuse</span> plane, bien limitée (<span class=\"kw-clinique\">bords nets</span>), pas de perles franches ; <span class=\"kw-imagerie\">fines perles en périphérie</span> parfois à peine visibles ; extension lente</td>\n            <td><span class=\"kw-clinique\">Tronc</span></td>\n            <td><span class=\"kw-clinique\">Eczéma</span>, <span class=\"kw-clinique\">plaque</span> de psoriasis, dermatophytose</td>\n          </tr>\n          <tr>\n            <th>CBC <strong><span class=\"kw-alerte\">sclérodermiforme</span></strong></th>\n            <td><strong><span class=\"kw-imagerie\">Cicatrice blanchâtre</span></strong>, dure, mal limitée, parfois atrophique ; <span class=\"kw-alerte\">extension profonde sous-évaluée</span></td>\n            <td><span class=\"kw-clinique\">Orifices de la face</span> (nez, paupières, oreille)</td>\n            <td>Atrophie cicatricielle banale → diagnostic tardif 🔥</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Communs aux 3 formes</strong> : toutes peuvent <span class=\"kw-clinique\">s'ulcérer</span> au cours de l'<span class=\"kw-clinique\">évolution</span> ; toutes peuvent être <span class=\"kw-clinique\">pigmentées</span> (la pigmentation n'a aucun lien avec l'évolutivité — c'est le piège des « CBC tatoués »).</p>\n      <div class=\"callout callout-warn\">\n        <strong>À compléter avec image.</strong> Sémio CBC nodulaire (le plus fréquent et le plus illustré) : <span class=\"kw-imagerie\">papule perlée translucide</span> + <span class=\"kw-imagerie\">télangiectasies</span> + <span class=\"kw-imagerie\">bordure perlée</span> caractéristique ⭐. Parfois centre ulcéré recouvert d'une <span class=\"kw-clinique\">croûte</span> (forme ulcéro-bourgeonnante).\n      </div>","frequence":2},{"id":"302-16","rang":"B","rubrique":"Contenu multimédia","titre":"Photographie d’un carcinome épidermoïde","contenu":"<p>Le CE invasif présente une <strong>triade sémiologique clé</strong> à reconnaître sur photographie :</p>\n      <ul>\n        <li><strong><span class=\"kw-imagerie\">Bourgeon</span></strong> (ou végétation <span class=\"kw-etio\">tumorale</span>) — tumeur charnue surélevée ;</li>\n        <li><strong><span class=\"kw-imagerie\">Ulcération</span></strong> centrale, à fond rouge, parfois sanieuse ;</li>\n        <li><strong><span class=\"kw-imagerie\">Croûte</span></strong> recouvrant l'<span class=\"kw-clinique\">ulcération</span>, saignant facilement après ablation.</li>\n      </ul>\n      <p>Caractères associés : <span class=\"kw-clinique\">induration</span> palpable de la base, <span class=\"kw-clinique\">saignement au contact</span>, parfois <span class=\"kw-alerte\">fixité aux plans profonds</span> (<span class=\"kw-alerte\">signe de gravité</span>). <strong><span class=\"kw-def\">Terrain</span></strong> : sujet âgé (<span class=\"kw-chiffre\">> 60 ans</span>), prédominance <span class=\"kw-clinique\">masculine</span>, en zone <span class=\"kw-clinique\">photo-exposée</span> (visage, dos des mains, lèvre inférieure, scalp chauve, pavillon de l'oreille).</p>\n      <p><strong>Signes de transformation</strong> d'une <span class=\"kw-clinique\">kératose</span> actinique préexistante en CE : <span class=\"kw-alerte\">surélévation</span>, <span class=\"kw-alerte\">induration</span>, <span class=\"kw-alerte\">saignement</span>, kératinisation en cornes — imposent une <span class=\"kw-bio\">biopsie</span> ou <span class=\"kw-ttt\">exérèse</span>.</p>\n      <div class=\"callout callout-warn\">\n        <strong>À compléter avec image.</strong> Sémio CE invasif = <span class=\"kw-clinique\">lésion</span> <span class=\"kw-imagerie\">bourgeonnante ulcéro-croûteuse indurée</span> saignant au contact, sur peau photo-exposée (visage, dos mains, lèvre inférieure) — souvent sur <span class=\"kw-clinique\">kératose</span> actinique préexistante.\n      </div>","frequence":1},{"id":"302-17","rang":"A","rubrique":"Contenu multimédia","titre":"Photographie d’un mélanome","contenu":"<p>Toute photographie de <span class=\"kw-clinique\">lésion</span> pigmentée suspecte impose d'appliquer <strong>la règle <span class=\"kw-clinique\">ABCDE</span></strong> + <strong>règle du <span class=\"kw-clinique\">vilain petit canard</span></strong>. Diagnostic évoqué si <span class=\"kw-chiffre\">≥ 2 critères ABCDE</span> présents.</p>\n      <ul>\n        <li><strong>A</strong>symétrie ;</li>\n        <li><strong>B</strong>ords irréguliers (encochés ou polycycliques) ;</li>\n        <li><strong>C</strong>ouleur inhomogène ;</li>\n        <li><strong>D</strong>iamètre <span class=\"kw-chiffre\">> 6 mm</span> (<span class=\"kw-alerte\">non spécifique</span>, attention au piège « <span class=\"kw-chiffre\">> 1 cm</span> ») ;</li>\n        <li><strong>É</strong>volution récente documentée.</li>\n      </ul>\n      <p><strong>Application aux 4 formes principales</strong> :</p>\n      <ul>\n        <li><strong>SSM</strong> — <span class=\"kw-imagerie\">macule rouge-brun</span> asymétrique à <span class=\"kw-clinique\">bords irréguliers</span>, polychrome (<span class=\"kw-chiffre\">60–70 %</span>) ;</li>\n        <li><strong><span class=\"kw-alerte\">Nodulaire</span></strong> — <span class=\"kw-imagerie\">nodule arrondi bleu/noir</span> (parfois achromique) ; <span class=\"kw-alerte\">n'applique PAS ABCDE</span> — c'est le critère <strong>É</strong>volution qui prime ;</li>\n        <li><strong>Dubreuilh (LLM)</strong> — <span class=\"kw-imagerie\">macule brunâtre du visage</span> chez sujet <span class=\"kw-chiffre\">> 60 ans</span>, féminin ;</li>\n        <li><strong>Acral lentigineux</strong> — <span class=\"kw-imagerie\">macule brune</span> à bords déchiquetés sur paume, plante ou appareil unguéal (<span class=\"kw-imagerie\">bande pigmentée ≥ 5 mm</span>).</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>À compléter avec image.</strong> Toujours appliquer <span class=\"kw-clinique\">ABCDE</span> + <span class=\"kw-clinique\">vilain petit canard</span> (<span class=\"kw-clinique\">lésion</span> discordante par rapport aux autres nævi du patient). En cas de doute → <span class=\"kw-bio\">dermatoscopie</span> par opérateur formé, et au moindre doute persistant → <strong><span class=\"kw-ttt\">exérèse</span> complète à visée diagnostique</strong>.\n      </div>","frequence":1}],"astuces":[],"strategie":{"urgence":"<p><strong>Degré :</strong> <span class=\"kw-alerte\">urgence diagnostique</span> (et non vitale) devant toute <span class=\"kw-etio\">lésion pigmentée suspecte de mélanome</span> ; <span class=\"kw-chiffre\">80%</span> des mélanomes sont repérés par le patient.<br><strong>Fenêtre :</strong> l'<span class=\"kw-alerte\">exérèse ne doit jamais être différée</span> — le <span class=\"kw-chiffre\">temps de réflexion est compressible</span>, l'<span class=\"kw-alerte\">urgence</span> diagnostique l'emporte.<br><strong>1er geste :</strong> <span class=\"kw-ttt\">exérèse complète à visée diagnostique</span> sous <span class=\"kw-ttt\">anesthésie locale</span>, emportant la tumeur jusqu'à l'<span class=\"kw-clinique\">hypoderme</span> — <span class=\"kw-alerte\">jamais de biopsie partielle</span> (sauf <span class=\"kw-clinique\">lésion</span> très étendue du visage).</p>","hospit":"<p><strong>Ambulatoire :</strong> <span class=\"kw-ttt\">exérèse-suture sous anesthésie locale</span> pour la majorité des carcinomes et des <span class=\"kw-clinique\">naevus</span>.<br><strong>Bloc / 2 temps :</strong> <span class=\"kw-ttt\">exérèse puis reconstruction sous anesthésie générale</span> (greffes, lambeaux) pour les lésions étendues ou péri-orificielles.<br><strong><span class=\"kw-def\">RCP</span> :</strong> indispensable pour le <span class=\"kw-etio\">CE groupe 2</span>, les formes complexes ou métastatiques, et avant <span class=\"kw-ttt\">vismodégib</span> ou <span class=\"kw-ttt\">immunothérapie</span>.<br><strong><span class=\"kw-def\">Annonce</span> :</strong> <span class=\"kw-ttt\">consultation d'annonce</span> systématique.</p>","redflags":"<ul><li><span class=\"kw-clinique\">Règle ABCDE</span> ≥ <span class=\"kw-chiffre\">2 critères</span> : <span class=\"kw-clinique\">Asymétrie</span>, <span class=\"kw-clinique\">Bords irréguliers</span>, <span class=\"kw-clinique\">Couleur inhomogène</span>, <span class=\"kw-clinique\">Diamètre > 6 mm</span>, <span class=\"kw-alerte\">Évolution récente</span> → <span class=\"kw-etio\">mélanome</span></li><li>Signe du <span class=\"kw-clinique\">vilain petit canard</span> : <span class=\"kw-clinique\">naevus</span> d'aspect discordant des autres chez un même patient</li><li><span class=\"kw-etio\">Mélanome nodulaire</span> : <span class=\"kw-alerte\">forme la plus agressive</span>, croissance verticale rapide, n'obéit pas à la règle <span class=\"kw-clinique\">ABCDE</span></li><li>Signes fonctionnels tardifs : <span class=\"kw-clinique\">prurit</span> ou <span class=\"kw-clinique\">saignement au contact</span></li><li><span class=\"kw-clinique\">Mélanonychie</span> : bande pigmentée <span class=\"kw-alerte\">évolutive (> 5 mm)</span> ou <span class=\"kw-alerte\">monodactylique</span> → craindre un <span class=\"kw-etio\">mélanome de l'appareil unguéal</span></li><li><span class=\"kw-clinique\">Halo naevus</span> de survenue tardive ou à halo irrégulier</li><li><span class=\"kw-clinique\">Kératose actinique</span> qui se cancérise : <span class=\"kw-alerte\">bourrelet induré</span>, <span class=\"kw-alerte\">ulcération</span>, <span class=\"kw-alerte\">rougeur excessive</span>, <span class=\"kw-alerte\">corne kératosique</span></li><li><span class=\"kw-etio\">Carcinome épidermoïde</span> avec <span class=\"kw-alerte\">signes neurologiques d'envahissement</span> (<span class=\"kw-clinique\">anesthésie du V</span>, <span class=\"kw-clinique\">paralysie faciale</span>) ou fixité aux plans profonds</li></ul>","principes":"<p>Le <span class=\"kw-ttt\">traitement de référence est chirurgical</span> (<span class=\"kw-ttt\">exérèse</span> complète) pour toutes les tumeurs malignes ; marges et traitements complémentaires dépendent du <span class=\"kw-etio\">type tumoral</span> et de la <span class=\"kw-def\">stratification pronostique</span>.</p><p><strong><span class=\"kw-clinique\">Mélanome</span></strong></p><p><span class=\"kw-ci\">Pas de radiothérapie ni de chimiothérapie</span> au <span class=\"kw-def\">stade</span> de tumeur primitive isolée.</p><ul><li><span class=\"kw-ttt\">Exérèse élargie complémentaire</span> : marges <span class=\"kw-chiffre\">conditionnées par l'indice de Breslow</span>, sans dépasser <span class=\"kw-chiffre\">2 cm</span> ; profondeur jusqu'au <span class=\"kw-clinique\">fascia</span> respecté</li><li><span class=\"kw-ttt\">Ganglion sentinelle</span> si <span class=\"kw-chiffre\">Breslow ≥ 1 mm</span> et/ou <span class=\"kw-alerte\">ulcération</span></li><li><span class=\"kw-etio\">Mélanome de Dubreuilh</span> intra-épidermique : marge de <span class=\"kw-chiffre\">1 cm</span> ou <span class=\"kw-ttt\">chirurgie de Mohs</span></li><li><span class=\"kw-def\">Stade</span> métastatique : <span class=\"kw-ttt\">thérapies ciblées anti-BRAF / anti-MEK</span> (mutation <span class=\"kw-etio\">BRAF V600</span> dans <span class=\"kw-chiffre\">50%</span>), <span class=\"kw-ttt\">immunothérapie anti-PD1 / anti-CTLA4</span>, <span class=\"kw-ttt\">chimiothérapie</span> (<span class=\"kw-ttt\">dacarbazine</span>, <span class=\"kw-ttt\">fotémustine</span>)</li></ul><p><strong>Carcinomes baso- et épidermoïde</strong></p><p><span class=\"kw-ttt\">Vismodégib</span> : <span class=\"kw-ci\">tératogène</span> ; <span class=\"kw-ttt\">radiothérapie</span> <span class=\"kw-ci\">contre-indiquée en cas de maladie génétique prédisposante</span>.</p><ul><li><span class=\"kw-ttt\">Exérèse chirurgicale</span> de 1re intention, marges <span class=\"kw-chiffre\">3-10 mm</span> selon le groupe pronostique (CE groupe 1 : <span class=\"kw-chiffre\">4-6 mm</span> ; groupe 2 : <span class=\"kw-chiffre\">> 6 mm</span>)</li><li>Formes superficielles : <span class=\"kw-ttt\">imiquimod topique</span> ou <span class=\"kw-ttt\">photothérapie dynamique</span></li><li>Si inopérable : <span class=\"kw-ttt\">radiothérapie</span> ou <span class=\"kw-ttt\">cryochirurgie</span></li><li><span class=\"kw-etio\">CBC</span> évolué/métastatique : <span class=\"kw-ttt\">vismodégib</span> (voie Hedgehog) ; <span class=\"kw-etio\">CE</span> métastatique : <span class=\"kw-ttt\">cisplatine</span>, <span class=\"kw-ttt\">anti-PD1</span></li></ul><p><strong>Précurseurs (<span class=\"kw-clinique\">kératose</span> actinique, maladie de Bowen)</strong></p><ul><li><span class=\"kw-clinique\">Kératose actinique</span> : traitement <span class=\"kw-ttt\">non chirurgical</span> (<span class=\"kw-ttt\">cryothérapie</span>, <span class=\"kw-ttt\">photothérapie dynamique</span>, <span class=\"kw-ttt\">5-FU</span> ou <span class=\"kw-ttt\">imiquimod</span> topiques)</li><li>Toute <span class=\"kw-alerte\">modification d'une kératose actinique</span> impose une <span class=\"kw-ttt\">biopsie / exérèse</span></li><li><span class=\"kw-etio\">Maladie de Bowen</span> (CE in situ) : <span class=\"kw-ttt\">exérèse chirurgicale</span>, ou <span class=\"kw-ttt\">cryothérapie</span> / <span class=\"kw-ttt\">5-FU</span> / <span class=\"kw-ttt\">photothérapie</span> dynamique</li></ul><p><strong>Prévention</strong></p><ul><li>Primaire : <span class=\"kw-ttt\">réduction de l'exposition aux UV</span> naturels et artificiels, <span class=\"kw-ttt\">photoprotection</span> essentielle dès l'enfance</li><li>Secondaire : <span class=\"kw-ttt\">dépistage</span> par examen cutané complet, <span class=\"kw-clinique\">règle ABCDE</span> + <span class=\"kw-clinique\">vilain petit canard</span>, <span class=\"kw-ttt\">auto-surveillance</span> enseignée à tous</li></ul>","suivi":"<p><strong>CBC :</strong> <span class=\"kw-ttt\">examen clinique annuel</span> pendant <span class=\"kw-chiffre\">≥ 5 ans</span> + auto-<span class=\"kw-def\">dépistage</span> et <span class=\"kw-ttt\">éviction solaire</span>.<br><strong>CE groupe 1 :</strong> <span class=\"kw-ttt\">examen clinique annuel ≥ 5 ans</span>, sans examen paraclinique.<br><strong>CE groupe 2 :</strong> clinique <span class=\"kw-chiffre\">tous les 3 mois</span> puis <span class=\"kw-chiffre\">tous les 6 mois ≥ 5 ans</span> + <span class=\"kw-imagerie\">échographie locorégionale</span> /<span class=\"kw-chiffre\">6 mois</span>.<br><strong><span class=\"kw-clinique\">Mélanome</span> / sujets à risque :</strong> <span class=\"kw-ttt\">surveillance médicale ≥ annuelle et à vie</span> + <span class=\"kw-ttt\">auto-surveillance</span> (<span class=\"kw-imagerie\">photographie</span>, <span class=\"kw-imagerie\">dermatoscopie</span>, calques).</p>"},"liensGlobaux":[{"href":"https://radiopaedia.org/articles/malignant-melanoma","label":"radiopaedia.org"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"<span class=\"kw-clinique\">Lésion</span> cutanée <span class=\"kw-etio\">tumorale</span> suspecte — Examen du tégument entier ± <span class=\"kw-imagerie\">dermatoscopie</span> · règle du <span class=\"kw-clinique\">vilain petit canard</span>","detail":"<h4>CAT — <span class=\"kw-clinique\">Tumeur cutanée</span> suspecte — De la <span class=\"kw-clinique\">lésion</span> suspecte à la décision chirurgicale (carcinomes & <span class=\"kw-clinique\">mélanome</span>)</h4>","branches":[{"to":"q-abcde","label":"Lésion pigmentée / mélanocytaire","color":"blue"},{"to":"q-perle","label":"Lésion kératinocytaire (perlée / bourgeonnante)","color":"blue"}]},{"id":"q-abcde","kind":"decision","label":"Règle ABCDE ≥ 2 critères ou aspect de vilain petit canard ?","branches":[{"to":"exerese","label":"Oui — critères présents / discordance","color":"red"},{"to":"t-surv","label":"Non — naevus typique stable","color":"green"}]},{"id":"exerese","kind":"decision","label":"<span class=\"kw-ttt\">Exérèse</span> complète à visée diagnostique — Sous <span class=\"kw-ttt\">anesthésie locale</span>, jusqu'à l'<span class=\"kw-clinique\">hypoderme</span> ; <span class=\"kw-alerte\">jamais de biopsie partielle</span>. <span class=\"kw-bio\">Histologie</span> : type, <span class=\"kw-chiffre\">Breslow</span>, <span class=\"kw-clinique\">ulcération</span>","branches":[{"to":"t-gs","label":"Breslow ≥ 1 mm et/ou ulcération","color":"red"},{"to":"t-elargie","label":"Breslow < 1 mm, sans ulcération","color":"amber"}]},{"id":"t-gs","kind":"terminal","label":"Exérèse élargie + ganglion sentinelle — Mélanome à risque ganglionnaire","color":"red","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Reprise d'exérèse élargie</span> : marges selon le <span class=\"kw-chiffre\">Breslow</span> (sans dépasser <span class=\"kw-chiffre\">2 cm</span>), jusqu'au <span class=\"kw-clinique\">fascia</span> respecté</li><li><span class=\"kw-ttt\">Recherche du ganglion sentinelle</span> (indiquée si <span class=\"kw-chiffre\">Breslow ≥ 1 mm</span> et/ou <span class=\"kw-alerte\">ulcération</span>)</li></ul><h4>Conduite</h4><ul><li>Micrométastase du <span class=\"kw-ttt\">ganglion sentinelle</span> → <span class=\"kw-etio\">stade IIIa</span> → <span class=\"kw-ttt\">traitement adjuvant 1 an</span> selon le profil mutationnel</li><li><span class=\"kw-def\">Stade</span> métastatique : <span class=\"kw-ttt\">immunothérapie</span> (anti-PD1 / anti-CTLA4), <span class=\"kw-ttt\">thérapie ciblée anti-BRAF / anti-MEK</span> si mutation <span class=\"kw-etio\">BRAF V600</span></li></ul>"},{"id":"t-elargie","kind":"terminal","label":"Exérèse élargie seule — Mélanome fin sans ulcération","color":"amber","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Reprise d'exérèse élargie seule</span>, marges conditionnées par le <span class=\"kw-chiffre\">Breslow</span> (≤ <span class=\"kw-chiffre\">2 cm</span>)</li><li><span class=\"kw-ci\">Pas de radiothérapie ni de chimiothérapie</span> au <span class=\"kw-def\">stade</span> de tumeur primitive</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-ttt\">Surveillance à vie</span> : <span class=\"kw-def\">dépistage</span> d'un <span class=\"kw-etio\">2nd mélanome</span> et des <span class=\"kw-etio\">carcinomes cutanés</span></li></ul>"},{"id":"t-surv","kind":"terminal","label":"Auto-surveillance + surveillance dermatologique","color":"green","detail":"<h4>Conduite</h4><ul><li>Pas d'<span class=\"kw-ttt\">exérèse préventive systématique</span> des <span class=\"kw-clinique\">naevus</span> communs</li><li><span class=\"kw-ttt\">Auto-surveillance</span> des lésions pigmentées enseignée à tous</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-ttt\">Surveillance dermatologique annuelle</span> si <span class=\"kw-clinique\">phototype clair</span>, <span class=\"kw-clinique\">naevus</span> nombreux (<span class=\"kw-chiffre\">> 50</span>) ou ATCD de <span class=\"kw-etio\">mélanome</span></li><li>Outils : <span class=\"kw-imagerie\">photographie</span>, <span class=\"kw-imagerie\">dermatoscopie</span>, calques de <span class=\"kw-def\">suivi</span></li></ul>"},{"id":"q-perle","kind":"decision","label":"Papule perlée translucide avec télangiectasies ?","branches":[{"to":"t-cbc","label":"Oui — papule perlée + télangiectasies","color":"amber"},{"to":"t-ce","label":"Non — tumeur bourgeonnante, ulcérée, croûteuse","color":"red"}]},{"id":"t-cbc","kind":"terminal","label":"CBC probable → exérèse chirurgicale","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Papule perlée</span> translucide, <span class=\"kw-clinique\">télangiectasies</span>, zones photo-exposées ; <span class=\"kw-alerte\">jamais sur les muqueuses</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Exérèse chirurgicale</span> (référence), marges <span class=\"kw-chiffre\">3-10 mm</span> avec contrôle histologique</li><li>Superficiel : <span class=\"kw-ttt\">imiquimod</span> / <span class=\"kw-ttt\">photothérapie dynamique</span> ; inopérable : <span class=\"kw-ttt\">radiothérapie</span> ; évolué : <span class=\"kw-ttt\">vismodégib</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-ttt\">Examen clinique annuel</span> pendant <span class=\"kw-chiffre\">≥ 5 ans</span></li></ul>"},{"id":"t-ce","kind":"terminal","label":"CE probable → exérèse + stratification pronostique","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Bourgeon</span>, <span class=\"kw-clinique\">ulcération</span>, <span class=\"kw-clinique\">croûte</span> ; rechercher fixité profonde et <span class=\"kw-clinique\">adénopathie</span> de <span class=\"kw-ttt\">drainage</span></li></ul><h4>Conduite</h4><ul><li>Stratifier : <span class=\"kw-etio\">groupe 1</span> (aucun critère) <span class=\"kw-bio\">vs</span> <span class=\"kw-etio\">groupe 2</span> (<span class=\"kw-chiffre\">≥ 1</span> <span class=\"kw-def\">critère de</span> mauvais <span class=\"kw-def\">pronostic</span> → <span class=\"kw-ttt\">RCP indispensable</span>)</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Exérèse chirurgicale</span> de 1re intention : marges <span class=\"kw-chiffre\">4-6 mm</span> (groupe 1), <span class=\"kw-chiffre\">> 6 mm</span> voire <span class=\"kw-chiffre\">1 cm</span> (groupe 2)</li><li>Métastatique : <span class=\"kw-ttt\">curage ganglionnaire</span> ± <span class=\"kw-ttt\">radiothérapie</span>, <span class=\"kw-ttt\">cisplatine</span>, <span class=\"kw-ttt\">anti-PD1</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Groupe 1 : clinique annuel <span class=\"kw-chiffre\">≥ 5 ans</span> ; groupe 2 : clinique /<span class=\"kw-chiffre\">3 mois</span> puis /<span class=\"kw-chiffre\">6 mois</span> + <span class=\"kw-imagerie\">échographie locorégionale</span> /<span class=\"kw-chiffre\">6 mois</span></li></ul>"}]},"cards":[{"i":"32bd8bd6fb4e","n":302,"o":"302-1","u":"Définition","t":"Connaître les principales tumeurs cutanées","q":"Quelles sont les principales catégories de tumeurs cutanées épithéliales bénignes et malignes ?","a":"<ul><li>Tumeur épithéliale <strong>bénigne</strong> : les <strong>verrues à HPV</strong>.</li><li>Tumeurs épithéliales <strong>malignes</strong> : le <strong>carcinome basocellulaire</strong> (CBC) et le <strong>carcinome épidermoïde</strong> (CE).</li></ul>"},{"i":"36396b78d11a","n":302,"o":"302-1","u":"Définition","t":"Connaître les principales tumeurs cutanées","q":"Quelles sont les principales catégories de tumeurs cutanées mélanocytaires bénignes et malignes ?","a":"<ul><li>Tumeur mélanocytaire <strong>bénigne</strong> : le <strong>nævus</strong> (grain de beauté).</li><li>Tumeur mélanocytaire <strong>maligne</strong> : le <strong>mélanome</strong>.</li></ul>"},{"i":"3a2b5572444a","n":302,"o":"302-1","u":"Définition","t":"Connaître les principales tumeurs cutanées","q":"Quelle est l'origine cellulaire des tumeurs cutanées ?","a":"<p>Les tumeurs cutanées se développent à partir de <strong>deux lignées cellulaires</strong> principales :</p><ul><li>Les <strong>kératinocytes</strong> (lignée épithéliale)</li><li>Les <strong>mélanocytes</strong> (lignée pigmentaire)</li></ul>"},{"i":"6ec1f002b77d","n":302,"o":"302-1","u":"Définition","t":"Connaître les principales tumeurs cutanées","q":"Quel est le facteur de risque commun des tumeurs cutanées, à l'exception des verrues à HPV ?","a":"<p>Le facteur de risque commun à la plupart des tumeurs cutanées, hormis les verrues à HPV, est l'<strong>exposition aux rayonnements ultraviolets</strong> (UVA, UVB, UVC).</p>"},{"i":"92bd48a84513","n":302,"o":"302-1","u":"Définition","t":"Connaître les principales tumeurs cutanées","q":"Quel est le mécanisme d'action des UVA et des UVB dans la carcinogenèse cutanée ?","a":"<ul><li>Les <strong>UVA</strong> ont une <strong>phototoxicité directe sur l'ADN</strong> et entraînent un <strong>stress oxydatif</strong> (production de ROS).</li><li>Les <strong>UVB</strong> sont <strong>mutagènes</strong> par la <strong>formation de dimères de pyrimidines</strong> dans l'ADN.</li></ul>"},{"i":"30acdfdf7d28","n":302,"o":"302-11","u":"Diagnostic positif","t":"Connaître les signes cliniques du mélanome","q":"Comment la règle du \"vilain petit canard\" aide-t-elle au diagnostic clinique du mélanome ?","a":"<p>La règle du \"vilain petit canard\" repose sur le principe que, chez un même patient, les nævus sont généralement similaires. La présence d'un <strong>nævus discordant</strong> par rapport aux autres lésions pigmentées du patient doit faire suspecter un mélanome et incite à une surveillance ou une exploration complémentaire.</p>"},{"i":"c36da82a7e36","n":302,"o":"302-11","u":"Diagnostic positif","t":"Connaître les signes cliniques du mélanome","q":"Quelles sont les manifestations cliniques des mélanomes unguéaux et muqueux, et quels signes fonctionnels tardifs peuvent être associés au mélanome ?","a":"<p>Les manifestations cliniques des mélanomes sont :</p><ul><li><strong>Mélanome unguéal</strong> : Se présente sous la forme d'une <strong>bande pigmentée longitudinale</strong> qui s'élargit et mesure typiquement <strong>au moins 5 mm</strong> de large.</li><li><strong>Mélanome muqueux</strong> : Apparaît comme une <strong>tache noire plane</strong> sur les muqueuses (anorectale, nasale, buccale).</li></ul><p>Les signes fonctionnels tardifs pouvant être associés à tout mélanome incluent le <strong>prurit</strong> (démangeaisons) et le <strong>saignement au contact</strong> de la lésion.</p>"},{"i":"c66fe7dbebe1","n":302,"o":"302-11","u":"Diagnostic positif","t":"Connaître les signes cliniques du mélanome","q":"Quels sont les cinq critères cliniques de la règle ABCDE permettant d'évoquer un mélanome ?","a":"<p>La règle ABCDE permet d'évoquer un mélanome si au moins deux critères sont présents :</p><ul><li><strong>A</strong>symétrie de la lésion.</li><li><strong>B</strong>ords irréguliers (encochés ou polycycliques).</li><li><strong>C</strong>ouleur inhomogène.</li><li><strong>D</strong>iamètre <strong>supérieur à 6 mm</strong> (et non pas 1 cm).</li><li><strong>É</strong>volution récente documentée (modification de taille, forme, couleur, relief).</li></ul>"},{"i":"ef2bf7d10ce6","n":302,"o":"302-11","u":"Diagnostic positif","t":"Connaître les signes cliniques du mélanome","q":"Quelles sont les caractéristiques principales du mélanome nodulaire, et pourquoi est-il considéré comme la forme la plus agressive ?","a":"<p>Le mélanome nodulaire représente <strong>10 à 30 %</strong> des mélanomes et peut survenir sur tous les terrains. Ses caractéristiques principales, qui en font la forme la plus agressive, sont :</p><ul><li>Il se présente généralement comme un <strong>nodule arrondi de couleur bleu/noir</strong>, mais peut parfois être achromique.</li><li>Il a une <strong>croissance verticale d'emblée</strong>, ce qui signifie qu'il n'y a <strong>pas de phase horizontale</strong> d'extension superficielle.</li><li>La règle ABCDE ne s'applique PAS systématiquement à cette forme, et le seul critère d'<strong>évolution</strong> (modification récente) suffit à en suspecter le diagnostic.</li></ul>"},{"i":"1ff98ce676ad","n":302,"o":"302-13","u":"Prise en charge","t":"Connaître les modalités de prévention du mélanome","q":"Quelles sont les mesures de prévention secondaire du mélanome ?","a":"<ul><li><strong>Formation des médecins</strong> à l'examen tégumentaire complet (règle <strong>ABCDE</strong> + <strong>signe du vilain petit canard</strong>).</li><li>Information de la population générale sur les <strong>signes d'appel</strong> et incitation à consulter sans tarder.</li><li><strong>Suivi dermatologique annuel à vie</strong> chez les patients à très haut risque (antécédent personnel de mélanome, syndrome des nævus atypiques) avec des outils comme la <strong>dermatoscopie</strong>, la surveillance photographique et les calques de suivi.</li><li>Enseignement de l'<strong>auto-surveillance</strong> à tous pour le repérage précoce des lésions suspectes.</li></ul>"},{"i":"3c07689679df","n":302,"o":"302-13","u":"Prise en charge","t":"Connaître les modalités de prévention du mélanome","q":"Quelle est la stratégie générale de prévention du mélanome, et quel profil d'exposition solaire est particulièrement visé ?","a":"<p>La prévention du mélanome repose sur deux axes : la <strong>prévention primaire</strong> (photoprotection) et la <strong>prévention secondaire</strong> (dépistage précoce). Le profil d'exposition à cibler prioritairement est celui des <strong>expositions intenses et intermittentes</strong>, en particulier durant l'<strong>enfance</strong>.</p>"},{"i":"9314846951de","n":302,"o":"302-13","u":"Prise en charge","t":"Connaître les modalités de prévention du mélanome","q":"Quelles sont les mesures clés de prévention primaire du mélanome ?","a":"<ul><li><strong>Éviter les expositions intenses et les coups de soleil</strong>, surtout pendant l'enfance.</li><li>Utiliser des <strong>vêtements couvrants</strong>, un <strong>chapeau</strong> et des <strong>lunettes de soleil</strong>.</li><li>Appliquer un <strong>écran solaire SPF 50+</strong> sur les zones découvertes.</li><li>Interdire absolument les <strong>cabines UV</strong>, classées cancérigènes certains (groupe 1 OMS).</li><li>Informer sur les risques liés aux UV naturels et artificiels.</li></ul>"},{"i":"030f869caf25","n":302,"o":"302-17","u":"Contenu multimédia","t":"Photographie d’un mélanome","q":"Quelle est la première approche clinique face à une photographie de lésion pigmentée suspecte pour évoquer un mélanome ?","a":"<p>Face à une photographie de lésion pigmentée suspecte, il faut appliquer la <strong>règle ABCDE</strong> et la <strong>règle du vilain petit canard</strong>.</p>"},{"i":"8a95adaa3f77","n":302,"o":"302-17","u":"Contenu multimédia","t":"Photographie d’un mélanome","q":"Quelles sont les démarches complémentaires à envisager en cas de doute persistant après l'évaluation clinique d'une lésion pigmentée suspecte à partir d'une photographie ?","a":"<p>En cas de doute, il faut avoir recours à la <strong>dermatoscopie</strong> réalisée par un opérateur formé. Si le doute persiste, une <strong>exérèse complète à visée diagnostique</strong> est indiquée.</p>"},{"i":"af919ba1ee0a","n":302,"o":"302-17","u":"Contenu multimédia","t":"Photographie d’un mélanome","q":"Quels sont les critères de la règle ABCDE permettant de suspecter un mélanome à partir d'une photographie, et à partir de combien de critères le diagnostic est-il évoqué ?","a":"<p>Les critères de la règle ABCDE sont :</p><ul><li><strong>A</strong>symétrie</li><li><strong>B</strong>ords irréguliers (encochés ou polycycliques)</li><li><strong>C</strong>ouleur inhomogène</li><li><strong>D</strong>iamètre <strong>&gt; 6 mm</strong> (attention, le piège est le &quot;&gt; 1 cm&quot;)</li><li><strong>É</strong>volution récente documentée</li></ul><p>Le diagnostic est évoqué si <strong>au moins 2 critères ABCDE</strong> sont présents.</p>"},{"i":"b30bfb56ad1d","n":302,"o":"302-17","u":"Contenu multimédia","t":"Photographie d’un mélanome","q":"Comment la règle ABCDE s'applique-t-elle aux 4 formes principales de mélanome ?","a":"<ul><li><strong>Mélanome à extension superficielle (SSM)</strong> : macule rouge-brun, asymétrique à bords irréguliers, polychrome (60-70% des cas). La règle ABCDE s'applique bien.</li><li><strong>Mélanome nodulaire</strong> : nodule arrondi bleu/noir (parfois achromique). La règle ABCDE ne s'applique PAS, c'est le critère d'<strong>Évolution</strong> qui prime.</li><li><strong>Mélanome de Dubreuilh (Lentigo Maligna Melanoma - LLM)</strong> : macule brunâtre du visage chez un sujet &gt; 60 ans, souvent féminin.</li><li><strong>Mélanome acral lentigineux</strong> : macule brune à bords déchiquetés sur la paume, la plante ou l'appareil unguéal (bande pigmentée <strong>≥ 5 mm</strong>).</li></ul>"},{"i":"fa5d9882499b","n":302,"o":"302-17","u":"Contenu multimédia","t":"Photographie d’un mélanome","q":"Que signifie la règle du \"vilain petit canard\" dans l'évaluation d'une lésion pigmentée suspecte documentée par une photographie ?","a":"<p>La règle du &quot;vilain petit canard&quot; signifie qu'il faut accorder une attention particulière à une <strong>lésion discordante par rapport aux autres nævi du patient</strong>. C'est celle qui se démarque des autres par son aspect.</p>"},{"i":"0cadafbeddba","n":302,"o":"302-2","u":"Diagnostic positif","t":"Connaître la présentation clinique d’une tumeur épithéliale bénigne à HPV","q":"Quelle est la présentation clinique typique des verrues vulgaires ?","a":"<p>Les verrues vulgaires se présentent comme des <strong>papules kératosiques rugueuses</strong>, à <strong>surface verruqueuse</strong>. Elles siègent le plus souvent aux <strong>mains et aux doigts</strong>, zones de microtraumatismes répétés.</p>"},{"i":"59d4a044827c","n":302,"o":"302-2","u":"Diagnostic positif","t":"Connaître la présentation clinique d’une tumeur épithéliale bénigne à HPV","q":"Décrire la présentation clinique des verrues plantaires.","a":"<p>Les verrues plantaires peuvent se présenter sous deux formes principales :</p><ul><li>Les <strong>myrmécies</strong> : une lésion unique et <strong>douloureuse à la pression</strong>.</li><li>Les <strong>verrues en mosaïque</strong> : des plages multiples qui coalescent.</li></ul><p>Elles siègent électivement aux <strong>points d'appui plantaires</strong>.</p>"},{"i":"8a4cd2c4478e","n":302,"o":"302-2","u":"Diagnostic positif","t":"Connaître la présentation clinique d’une tumeur épithéliale bénigne à HPV","q":"Comment définir une verrue à HPV ?","a":"<p>Une verrue à HPV est une <strong>tumeur épithéliale bénigne</strong> de la peau, résultant de l'infection des kératinocytes par un <strong>papillomavirus humain (HPV)</strong>.</p>"},{"i":"0ded3cac9834","n":302,"o":"302-4","u":"Prise en charge","t":"Connaître les principes de la prise en charge globale des tumeurs cutanées","q":"Quels sont les quatre axes principaux de la prise en charge d'une tumeur cutanée suspecte, communs aux carcinomes basocellulaires (CBC), spinocellulaires (CE) et mélanomes ?","a":"<p>Les quatre axes sont :</p><ul><li>La <strong>confirmation histologique préalable</strong>.</li><li>L'<strong>exérèse chirurgicale</strong>, qui est le traitement de référence.</li><li>La <strong>discussion en Réunion de Concertation Pluridisciplinaire (RCP)</strong> en cas de situations spécifiques.</li><li>Le <strong>suivi clinique</strong> et la prévention.</li></ul>"},{"i":"5470287dd0de","n":302,"o":"302-4","u":"Prise en charge","t":"Connaître les principes de la prise en charge globale des tumeurs cutanées","q":"Dans la prise en charge des tumeurs cutanées, dans quelles situations une Réunion de Concertation Pluridisciplinaire (RCP) est-elle indispensable ?","a":"<p>Une RCP est indispensable dans les cas suivants :</p><ul><li>Forme évoluée de la tumeur.</li><li>Carcinome spinocellulaire (CE) du groupe 2 (avec au moins <strong>1 facteur de risque de mauvais pronostic</strong>).</li><li>Mélanome de stade <strong>III ou IV</strong>.</li><li>Lorsque la chirurgie n'est pas réalisable d'emblée.</li></ul>"},{"i":"5d8d4a9c25a1","n":302,"o":"302-4","u":"Prise en charge","t":"Connaître les principes de la prise en charge globale des tumeurs cutanées","q":"Quelle est la règle concernant la gestion d'une lésion pigmentée très suspecte de mélanome, et quelle est l'exception à cette règle ?","a":"<p>Toute lésion pigmentée très suspecte de mélanome impose une <strong>exérèse complète d'emblée</strong>, avec des marges macroscopiques d'environ <strong>1 cm</strong>. Il ne faut <strong>JAMAIS</strong> réaliser de biopsie partielle, sauf pour une <strong>lésion de très grande taille</strong> dont l'exérèse totale serait délabrante (par exemple, sur le visage).</p>"},{"i":"66fad24d3c98","n":302,"o":"302-4","u":"Prise en charge","t":"Connaître les principes de la prise en charge globale des tumeurs cutanées","q":"Quel est le principe du suivi après traitement d'une tumeur cutanée et quelles mesures préventives sont à enseigner au patient ?","a":"<p>Le suivi repose sur un <strong>suivi clinique annuel à vie</strong> (au moins 5 ans). Les mesures préventives à enseigner sont :</p><ul><li>L'<strong>auto-dépistage</strong> régulier.</li><li>Une <strong>photoprotection renforcée</strong>.</li></ul>"},{"i":"93308920201f","n":302,"o":"302-4","u":"Prise en charge","t":"Connaître les principes de la prise en charge globale des tumeurs cutanées","q":"Dans la prise en charge des tumeurs cutanées, quelle est la méthode de confirmation histologique à privilégier et dans quels cas une biopsie est-elle envisagée ?","a":"<p>La méthode à privilégier est l'<strong>exérèse à visée diagnostique d'emblée</strong> si le diagnostic de tumeur cutanée est très probable. Une <strong>biopsie préalable</strong> est envisagée pour les diagnostics incertains, les chirurgies complexes, ou les localisations délicates comme la zone orbitopalpébrale.</p>"},{"i":"99bb48a988ed","n":302,"o":"302-4","u":"Prise en charge","t":"Connaître les principes de la prise en charge globale des tumeurs cutanées","q":"Comment les marges d'exérèse chirurgicale sont-elles définies pour les carcinomes basocellulaires (CBC), carcinomes spinocellulaires (CE) et les mélanomes ?","a":"<p>Les marges sont :</p><ul><li>Pour les CBC et CE : <strong>3 à 10 mm</strong> de marges latérales.</li><li>Pour les mélanomes : Les marges sont conditionnées par le <strong>Breslow</strong>, avec un maximum de <strong>2 cm</strong>. L'anesthésie locale est la règle, et le fascia est respecté.</li></ul>"},{"i":"04657949f5ca","n":302,"o":"302-5","u":"Diagnostic positif","t":"Connaître la présentation clinique et la démarche diagnostique devant un carcinome basocellulaire, épidermoïde","q":"Quelles sont les principales variétés cliniques du carcinome basocellulaire (CBC) ?","a":"<ul><li><strong>Nodulaire</strong> (la plus fréquente) : une papule perlée du visage.</li><li><strong>Superficiel/Pagétoïde</strong> : une plaque érythémato-squameuse du tronc avec des bords nets et de fines perles en périphérie.</li><li><strong>Sclérodermiforme</strong> : un aspect de cicatrice blanchâtre mal limitée au niveau des orifices de la face, dont l'extension profonde est sous-évaluée. Il s'agit de la forme la plus grave et la plus rare.</li></ul>"},{"i":"12bff4b469fc","n":302,"o":"302-5","u":"Diagnostic positif","t":"Connaître la présentation clinique et la démarche diagnostique devant un carcinome basocellulaire, épidermoïde","q":"Quelle est la démarche diagnostique devant une suspicion de carcinome basocellulaire ou épidermoïde ?","a":"<p>La démarche diagnostique repose d'abord sur un <strong>bilan clinique</strong> recherchant une fixité aux plans profonds, un éventuel déficit nerveux (V, VII) et un examen des aires de drainage. Une <strong>biopsie</strong> est recommandée si le diagnostic est incertain ou si la chirurgie est complexe (orbitopalpébrale). Une <strong>exérèse chirurgicale large d'emblée</strong> avec analyse anatomopathologique des marges est envisagée si le diagnostic est très probable.</p>"},{"i":"3199cbf03602","n":302,"o":"302-5","u":"Diagnostic positif","t":"Connaître la présentation clinique et la démarche diagnostique devant un carcinome basocellulaire, épidermoïde","q":"Quels sont les signes cliniques clés d'un carcinome épidermoïde (CE) invasif ?","a":"<p>Les signes cliniques clés, souvent associés, d'un carcinome épidermoïde (CE) invasif sont un <strong>bourgeon</strong> + une <strong>ulcération</strong> + une <strong>croûte</strong>. Il s'agit d'une tumeur <strong>indurée saignant facilement</strong>. Le CE peut apparaître sur les zones photo-exposées cutanées et muqueuses (par exemple, <strong>lèvre inférieure, gland</strong>).</p>"},{"i":"68e124dc58a3","n":302,"o":"302-5","u":"Diagnostic positif","t":"Connaître la présentation clinique et la démarche diagnostique devant un carcinome basocellulaire, épidermoïde","q":"Quel piège classique faut-il connaître concernant le carcinome basocellulaire (CBC) sclérodermiforme ?","a":"<p>Le <strong>piège classique</strong> concernant le carcinome basocellulaire (CBC) sclérodermiforme est son <strong>aspect de cicatrice blanchâtre banale, mal limitée</strong>. Cela conduit souvent à un diagnostic tardif et à une sous-estimation de son extension profonde. Il faut penser au CBC devant <strong>toute cicatrice apparue spontanément</strong> en zone photo-exposée.</p>"},{"i":"80f51525818b","n":302,"o":"302-5","u":"Diagnostic positif","t":"Connaître la présentation clinique et la démarche diagnostique devant un carcinome basocellulaire, épidermoïde","q":"Quelles sont les caractéristiques anatomopathologiques d'un carcinome épidermoïde (CE) ?","a":"<p>Les caractéristiques anatomopathologiques d'un carcinome épidermoïde (CE) comprennent des <strong>kératinocytes malpighiens de grande taille</strong> disposés en lobules ou travées, présentant des <strong>atypies cytonucléaires</strong>, la présence de <strong>globes cornés</strong> et de <strong>ponts d'union</strong>. On observe un <strong>envahissement dermique</strong>, potentiellement accompagné d'un envahissement hypodermique.</p>"},{"i":"98efd1c69db5","n":302,"o":"302-5","u":"Diagnostic positif","t":"Connaître la présentation clinique et la démarche diagnostique devant un carcinome basocellulaire, épidermoïde","q":"Comment se présente cliniquement un carcinome basocellulaire (CBC) ?","a":"<p>Un carcinome basocellulaire (CBC) se présente typiquement comme une <strong>papule rouge/rosée translucide</strong>, en relief, arrondie, recouverte de <strong>télangiectasies</strong>, de croissance lente. Il peut parfois présenter une <strong>bordure perlée caractéristique en couronne</strong>. Sa localisation préférentielle est sur les <strong>zones photo-exposées (visage ++)</strong>, et il n'est <strong>JAMAIS retrouvé sur les muqueuses</strong>.</p>"},{"i":"c1b9978e9b58","n":302,"o":"302-5","u":"Diagnostic positif","t":"Connaître la présentation clinique et la démarche diagnostique devant un carcinome basocellulaire, épidermoïde","q":"Quels sont les précurseurs du carcinome épidermoïde (CE) ?","a":"<p>Le carcinome épidermoïde (CE) peut se développer sur des précurseurs tels que la <strong>kératose actinique</strong> (cutanée), la <strong>leucoplasie</strong> (muqueuse, associée au tabac et aux UV), ou la <strong>maladie de Bowen</strong> (carcinome in situ intra-épidermique). Il peut aussi survenir <em>de novo</em>.</p>"},{"i":"df8533bdacbe","n":302,"o":"302-5","u":"Diagnostic positif","t":"Connaître la présentation clinique et la démarche diagnostique devant un carcinome basocellulaire, épidermoïde","q":"Comment l'anatomopathologie permet-elle de diagnostiquer un carcinome basocellulaire (CBC) ?","a":"<p>L'anatomopathologie d'un carcinome basocellulaire (CBC) révèle des <strong>lobules de kératinocytes basophiles (basaloïdes)</strong> en <strong>disposition palissadique en périphérie</strong>, avec des <strong>fentes de rétraction</strong>. On distingue quatre sous-types histologiques.</p>"},{"i":"53ad6ad60eda","n":302,"o":"302-7","u":"Prise en charge","t":"Connaître la prévention des carcinomes épidermoïdes et basocellulaires","q":"Quelles sont les mesures de photoprotection recommandées pour la prévention primaire des carcinomes cutanés ?","a":"<p>Les mesures de photoprotection incluent :</p><ul><li>Éviter les expositions solaires aux heures de fort ensoleillement (<strong>11h–16h</strong>).</li><li>Porter des <strong>vêtements couvrants</strong>, un <strong>chapeau à larges bords</strong> et des <strong>lunettes de soleil</strong>.</li><li>Appliquer un écran solaire avec un <strong>SPF ≥ 50</strong> sur les zones découvertes, et le renouveler <strong>toutes les 2 heures</strong>.</li><li>Interdiction absolue des <strong>cabines de bronzage UV</strong>, classées <strong>cancérogènes certains (groupe 1 OMS)</strong>.</li><li>Mettre en place une <strong>photoprotection renforcée chez l'enfant</strong>.</li></ul>"},{"i":"abfb12479360","n":302,"o":"302-7","u":"Prise en charge","t":"Connaître la prévention des carcinomes épidermoïdes et basocellulaires","q":"Quelle est la stratégie générale de prévention des carcinomes cutanés basocellulaires et épidermoïdes ?","a":"<p>La prévention des carcinomes cutanés repose sur deux axes complémentaires :</p><ul><li>La <strong>photoprotection</strong> (prévention primaire).</li><li>Le <strong>dépistage des lésions précancéreuses</strong> (prévention secondaire).</li></ul>"},{"i":"ccc8863e6155","n":302,"o":"302-7","u":"Prise en charge","t":"Connaître la prévention des carcinomes épidermoïdes et basocellulaires","q":"Pourquoi les cabines de bronzage sont-elles formellement contre-indiquées dans la prévention des carcinomes cutanés ?","a":"<p>Les cabines de bronzage UV sont <strong>formellement contre-indiquées</strong> car elles sont classées <strong>cancérogènes certains (groupe 1 OMS)</strong>, au même rang que le tabac et l'amiante. Le bronzage, qu'il soit naturel ou artificiel, est un signal d'agression de l'ADN par les UV et non un signe de bonne santé.</p>"},{"i":"ee4279157aad","n":302,"o":"302-7","u":"Prise en charge","t":"Connaître la prévention des carcinomes épidermoïdes et basocellulaires","q":"Quels sont les principes du dépistage secondaire des carcinomes cutanés et de leurs précurseurs ?","a":"<p>Le dépistage secondaire comprend :</p><ul><li>Le dépistage du carcinome épidermoïde et de ses précurseurs est recommandé <strong>après 50 ans</strong> chez les sujets à risque (<strong>phototype I–II</strong>, <strong>antécédents personnels ou familiaux</strong>, <strong>immunodéprimés</strong>, <strong>transplantés rénaux</strong>).</li><li>Le traitement précoce des <strong>kératoses actiniques</strong> par cryothérapie à l'azote liquide, <strong>5-FU topique</strong>, <strong>imiquimod crème</strong>, ou photothérapie dynamique.</li><li>L'enseignement de l'<strong>autosurveillance</strong> et un <strong>examen tégumentaire annuel</strong> chez les patients à très haut risque.</li></ul>"},{"i":"22a60f10fc71","n":302,"o":"302-8","u":"Définition","t":"Connaître la définition et les principaux facteurs de risque des nævi","q":"Quels sont les principaux facteurs de risque associés aux nævi mélanocytaires ?","a":"<ul><li><strong>Phototype clair</strong> (I-II).</li><li><strong>Exposition solaire</strong> intermittente et intense, surtout pendant l'enfance.</li><li><strong>Immunodépression</strong> (transplantés, traitements immunosuppresseurs, infection VIH).</li><li><strong>Facteurs génétiques</strong>, notamment le syndrome des nævus atypiques.</li></ul>"},{"i":"4f0fd854b699","n":302,"o":"302-8","u":"Définition","t":"Connaître la définition et les principaux facteurs de risque des nævi","q":"Quelle est la définition d'un nævus mélanocytaire ?","a":"<p>Un nævus mélanocytaire est une <strong>prolifération bénigne de mélanocytes</strong>, groupés en thèques (amas cellulaires), localisée dans l'épiderme et/ou le derme. C'est la tumeur mélanocytaire la plus fréquente, présente chez tous les individus.</p>"},{"i":"5d81f68fbaa0","n":302,"o":"302-8","u":"Définition","t":"Connaître la définition et les principaux facteurs de risque des nævi","q":"Quelle est l'histoire naturelle typique des nævi mélanocytaires ?","a":"<p>Les nævi apparaissent généralement vers <strong>4-5 ans</strong>, atteignent un plateau vers <strong>40 ans</strong> (environ 20 nævi en moyenne), puis régressent progressivement et se raréfient après <strong>60 ans</strong>. Une augmentation de taille et de pigmentation est possible durant la grossesse.</p>"},{"i":"8168593c5dee","n":302,"o":"302-8","u":"Définition","t":"Connaître la définition et les principaux facteurs de risque des nævi","q":"Quelles sont les trois principales formes anatomopathologiques du nævus mélanocytaire selon la répartition des thèques ?","a":"<ul><li><strong>Nævus jonctionnel</strong> : les thèques sont situées dans la couche basale de l'épiderme, prédominant chez l'enfant.</li><li><strong>Nævus dermique</strong> : strictement intradermique, souvent tubéreux ou papuleux.</li><li><strong>Nævus mixte (composé)</strong> : présence d'une composante jonctionnelle et d'une composante dermique.</li></ul>"}]};